/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A47 staging source: frozen manifest honoraria–huddle; audit and publish every 20 lemmas. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});
D('honoraria',{etymology:E('Honoraria is the plural of honorarium, from Latin honorarium, a payment or honor given for a service. It commonly refers to fees paid to speakers or professionals when the work is not priced as a regular salary.','honoraria'),contexts:[C('honoraria.s1','学术会议','The conference budget lists modest honoraria for the three guest speakers, separate from their travel reimbursements.','会议预算为三位特邀演讲者列出适度酬金，并与差旅报销分开。','The conference budget lists modest honoraria / for the three guest speakers / separate from their travel reimbursements.','honoraria 是 honorarium 的复数，指向演讲者或专业人士支付的酬金。','句中为三位演讲者列出多笔酬金。')],mistakes:[M('The invoice called one speaker payment several honoraria, although it recorded only a single honorarium.','The invoice listed honorarium for one speaker and honoraria for several speakers.','honoraria 是复数形式，单数为 honorarium。')],quiz:[Q('honoraria',1,1,'Honoraria are usually?','fees paid for a service such as a guest talk','monthly rent for an apartment','taxes on inherited property','fees paid for a service such as a guest talk','honoraria 指向演讲者或专业人士支付的酬金。'),Q('honoraria',2,1,'Which sentence uses honoraria as a plural?','The panelists received honoraria after their talks.','The panelist received one honoraria.','The honoraria is a person who hosted the event.','The panelists received honoraria after their talks.','多个演讲者收到多笔酬金时用复数 honoraria。','grammar'),Q('honoraria',3,1,'The singular form of honoraria is?','honorarium','honorary','honourable','honorarium','honoraria 是 honorarium 的复数形式。','word-formation'),Q('honoraria',4,1,'A conference might budget honoraria for?','invited speakers','the folding chairs only','unpaid parking tickets','invited speakers','会议可能向特邀演讲者支付酬金。')]});
D('honorarium',{etymology:E('Honorarium comes from Latin honorarium, literally a payment connected with honor. In English it is money given for a professional service, often when no fixed salary or fee has been set.','honorarium'),contexts:[C('honorarium.s1','公益讲座','The museum offered the visiting historian an honorarium for delivering a public lecture, although she declined the payment.','博物馆为来访历史学家举办公开讲座提供了一笔酬金，但她谢绝了这笔钱。','The museum offered the visiting historian an honorarium / for delivering a public lecture / although she declined the payment.','honorarium 指因提供服务而支付的一笔酬金。','讲座酬谢是一笔 honorarium，不是固定工资。')],mistakes:[M('The contract described the historian’s monthly salary as a one-time honorarium paid after a single lecture.','The museum called the one-time lecture payment an honorarium.','honorarium 通常指单次服务酬谢，不是持续发放的月薪。')],quiz:[Q('honorarium',1,1,'An honorarium is?','money paid for a service, often without a fixed fee','a title inherited by the eldest child','a device used to warn traffic','money paid for a service, often without a fixed fee','honorarium 是因服务支付的酬金。'),Q('honorarium',2,1,'Which payment is most likely an honorarium?','a small thank-you payment for a guest lecture','a regular monthly wage under an employment contract','a refund for a returned item','a small thank-you payment for a guest lecture','特邀讲座后的酬谢最符合 honorarium。'),Q('honorarium',3,1,'Honorarium is related historically to?','honor','horizon','hoof','honor','其拉丁词源与 honor（荣誉）有关。','word-formation'),Q('honorarium',4,1,'The plural of honorarium is?','honoraria','honorariums only','honorary','honoraria','常见复数形式是 honoraria。','grammar')]});
D('honorary',{etymology:E('Honorary comes from honor with the adjective-forming suffix -ary. It means awarded to honor someone, often without the usual study, work, or formal requirements.','honorary'),contexts:[C('honorary.s1','大学典礼','The university awarded the longtime community volunteer an honorary degree in recognition of her work, without requiring a course of study.','大学为表彰这位长期服务社区的志愿者授予荣誉学位，并未要求她修读课程。','The university awarded the longtime community volunteer an honorary degree / in recognition of her work / without requiring a course of study.','honorary 表示为表彰某人而授予的，不要求通常的资格过程。','荣誉学位是表彰性质，不需完成常规课程。')],mistakes:[M('The student called her degree honorary because she completed all required courses and examinations in the standard program.','The student called the degree honorary because it was awarded without the usual academic requirements.','完成常规学业要求的学位不因此成为 honorary degree。')],quiz:[Q('honorary',1,1,'An honorary degree is typically?','awarded as recognition without the usual study requirements','earned by completing a standard course only','a fee paid to a lecturer','awarded as recognition without the usual study requirements','honorary 表示荣誉授予，不必完成通常学业。'),Q('honorary',2,1,'Which is an honorary role?','a title given to recognize service','a paid shift with required daily duties','a tool for hanging a coat','a title given to recognize service','荣誉头衔用于表彰贡献。'),Q('honorary',3,1,'Honorary is formed from honor plus?','-ary','-less','-hood','-ary','-ary 构成与荣誉有关的形容词。','word-formation'),Q('honorary',4,1,'A person receiving an honorary award is being?','recognized','deceived','measured','recognized','honorary award 是表彰性授予。')]});
D('honourable',{etymology:E('Honourable is the British spelling of honorable, formed from honour plus -able. It means deserving respect for honesty, fairness, or principled conduct.','honourable'),contexts:[C('honourable.s1','体育精神','After realizing that the referee had missed a foul, the captain made the honourable choice to tell the official what had happened.','队长发现裁判漏判一次犯规后，作出了诚实正直的选择，主动告知裁判实际情况。','After realizing that the referee had missed a foul / the captain made the honourable choice / to tell the official / what had happened.','honourable 指值得尊敬、诚实正直的。','队长主动说明对己方不利的事实，体现正直。')],mistakes:[M('The report called the captain honourable for hiding the foul and knowingly misleading the referee.','The report called the captain honourable for honestly reporting the missed foul.','故意隐瞒事实不符合 honourable 所表达的正直。')],quiz:[Q('honourable',1,1,'An honourable action is?','honest and deserving respect','dishonest but profitable','a type of flying vehicle','honest and deserving respect','honourable 表示正直、值得尊敬。'),Q('honourable',2,1,'Which is an honourable choice?','admitting a mistake even when it is embarrassing','blaming an innocent teammate','concealing evidence for personal gain','admitting a mistake even when it is embarrassing','承认错误体现诚实。'),Q('honourable',3,1,'Honourable is the usual spelling in?','British English','only mathematical notation','informal American texting only','British English','honourable 是英式拼法，honorable 是美式拼法。','grammar'),Q('honourable',4,1,'The suffix -able means roughly?','worthy of or capable of','without','a group of','worthy of or capable of','-able 可表示值得或能够。','word-formation')]});
D('hoodwink',{etymology:E('Hoodwink combines hood with wink. It originally referred to covering someone’s eyes, and developed into the verb meaning to deceive someone into believing something false.','hoodwink'),contexts:[C('hoodwink.s1','消费提醒','The fake seller tried to hoodwink buyers with a forged certificate, but the registry check exposed the document.','假卖家试图用伪造证书蒙骗买家，但登记信息核查揭穿了文件。','The fake seller tried to hoodwink buyers / with a forged certificate / but the registry check / exposed the document.','hoodwink 指欺骗某人，使其相信虚假信息。','伪造证书意在使买家相信卖家拥有真实资质。')],mistakes:[M('The guide hoodwinked visitors by clearly explaining every fee and showing the authentic permit.','The guide tried to hoodwink visitors by hiding the fee and presenting a false permit.','公开说明真实费用和证件不是欺骗。')],quiz:[Q('hoodwink',1,1,'To hoodwink someone is to?','deceive them into believing something false','welcome them warmly','move them to a new house','deceive them into believing something false','hoodwink 表示蒙骗。'),Q('hoodwink',2,1,'Which action could hoodwink customers?','using a forged certificate to make a false claim','posting accurate prices in advance','answering questions truthfully','using a forged certificate to make a false claim','伪造证书是误导顾客的欺骗行为。'),Q('hoodwink',3,1,'Hoodwink is usually used as a?','verb','measurement unit','plural pronoun','verb','hoodwink 作动词表示欺骗。','grammar'),Q('hoodwink',4,1,'A hoodwinked buyer has been?','misled','honored with a degree','given an airtight jar','misled','受骗者被误导了。')]});
D('hoof',{etymology:E('Hoof comes from Old English hōf and names the hard covering of the foot in horses, cattle, deer, and related animals. Informally, hoof can also be a verb meaning to kick or walk.','hoof'),contexts:[C('hoof.s1','兽医检查','The veterinarian cleaned the horse’s hoof and checked for a stone lodged near the edge.','兽医清理了马蹄，并检查边缘附近是否嵌有石子。','The veterinarian cleaned the horse’s hoof / and checked / for a stone lodged near the edge.','hoof 在此指马蹄的坚硬外壳。','清理并检查马脚边缘的石子是检查蹄部。')],mistakes:[M('The trainer examined the horse’s hoof, the soft feather covering its back.','The trainer examined the horse’s hoof, the hard covering around its foot.','hoof 是动物脚部的坚硬蹄壳，不是背部羽毛。')],quiz:[Q('hoof',1,1,'A horse’s hoof is?','the hard covering of its foot','a feather on its back','a horn used for music','the hard covering of its foot','hoof 指马等动物脚上的蹄。'),Q('hoof',2,1,'Which animal has hooves?','a deer','a trout','a butterfly','a deer','鹿有蹄。'),Q('hoof',3,2,'In informal use, to hoof it can mean to?','walk, or kick with a hoof','receive an honorary title','deceive a buyer','walk, or kick with a hoof','hoof 也可非正式地表示步行或踢。'),Q('hoof',4,1,'The common plural of hoof is?','hooves','hoofes','hoofs only','hooves','hooves 是常见复数形式。','grammar')]});
D('hook',{etymology:E('Hook comes from Old English hōc, a curved or projecting object. It can name a hanger or barbed fishing tool, mean to fasten or catch with one, attract attention, or refer to a short curved punch.','hook'),contexts:[C('hook.s1','家居整理','She hung the raincoat on a sturdy hook beside the door so it could dry before the next walk.','她把雨衣挂在门边结实的挂钩上，让它在下次出门前晾干。','She hung the raincoat on a sturdy hook / beside the door / so it could dry / before the next walk.','hook 在此指用于悬挂物品的弯钩。','雨衣挂在门旁的弯钩上，符合挂钩义。')],mistakes:[M('He hung the coat on a flat plate with no curved end and called the plate a hook.','He hung the coat on a curved hook fixed beside the door.','用于挂物的 hook 通常有弯曲或突出的部分。')],quiz:[Q('hook',1,1,'A coat hook is used to?','hang clothing','measure horsepower','make a loud warning sound','hang clothing','挂衣钩用来悬挂衣物。'),Q('hook',2,2,'A fishing hook often has?','a curved shape and a barb','a soft plant stem','a flat level surface','a curved shape and a barb','鱼钩弯曲并常带倒刺以便钩住鱼。'),Q('hook',3,4,'A strong opening line can hook readers by?','making them interested','putting a coat on a hanger','measuring an hour','making them interested','hook 可比喻吸引人的注意或兴趣。'),Q('hook',4,5,'In boxing, a hook is?','a short curved punch','an award for service','a soft drink','a short curved punch','hook 也可指弧线拳。')]});
D('hooked',{etymology:E('Hooked is the past participle of hook and also an adjective. It can mean bent into a hook-like shape, or figuratively unable to stop using something or deeply interested in it.','hooked'),contexts:[C('hooked.s2','阅读习惯','After the first chapter ended on a mystery, Ren was hooked and stayed up late to finish the novel.','第一章以一个谜团收尾后，任被深深吸引，熬夜读完了小说。','After the first chapter ended on a mystery / Ren was hooked / and stayed up late / to finish the novel.','hooked 在此表示被深深吸引、欲罢不能。','主人公连续读完小说，显示他被故事吸引。')],mistakes:[M('The reviewer said she was hooked on the series but stopped watching after five minutes because it held no interest.','The reviewer said she was hooked on the series and eagerly watched each episode.','hooked 表示兴趣强烈或沉迷，与很快失去兴趣相反。')],quiz:[Q('hooked',1,1,'A person hooked on a mystery novel is?','deeply interested and eager to continue','unable to understand any sentence','wearing a metal shoe','deeply interested and eager to continue','hooked 可表示被某物深深吸引。'),Q('hooked',2,1,'A hooked beak is?','curved like a hook','flat and level','made of paper','curved like a hook','hooked 也可形容弯钩状的。'),Q('hooked',3,2,'“He is hooked on the game” suggests he?','cannot easily stop playing or is strongly interested','has never heard of the game','is hosting a formal dinner','cannot easily stop playing or is strongly interested','hooked on 表示沉迷或着迷。'),Q('hooked',4,1,'Which phrase uses hooked figuratively?','hooked on a popular podcast','a hooked fishing line with a curved end only','hooked a coat onto the door','hooked on a popular podcast','对播客着迷是比喻用法。')]});
D('hoot',{etymology:E('Hoot is imitative in origin, echoing a short, loud call. It names a horn-like sound or means to laugh at or jeer, often with the phrase not give a hoot for not caring.','hoot'),contexts:[C('hoot.s1','夜间观察','A distant owl gave a low hoot from the trees, and the hikers paused to listen in the dark.','远处树林里传来猫头鹰低沉的一声鸣叫，徒步者停下来在黑暗中聆听。','A distant owl gave a low hoot / from the trees / and the hikers paused / to listen in the dark.','hoot 在此指类似号角或猫头鹰的短促响声。','猫头鹰发出的低鸣是 hoot。')],mistakes:[M('The hikers heard a silent flash of light and described it as a loud hoot.','The hikers heard a loud call from the owl and described it as a hoot.','hoot 是可听见的鸣叫或号声，不是闪光。')],quiz:[Q('hoot',1,1,'An owl’s hoot is?','a short loud call','a curved metal hanger','a payment for a lecture','a short loud call','hoot 常指猫头鹰等发出的短促鸣叫。'),Q('hoot',2,1,'To hoot at a performer can mean to?','jeer or laugh at them','award them an honorary degree','tend their cattle','jeer or laugh at them','hoot 也可指嘲笑或喝倒彩。'),Q('hoot',3,1,'“I don’t give a hoot” means?','I do not care at all','I am extremely hopeful','I am measuring the horizon','I do not care at all','该习语表示一点也不在乎。'),Q('hoot',4,1,'Hoot probably developed through?','imitation of a sound','a term for housework','the name of a horse','imitation of a sound','hoot 的词源具有拟声性质。','word-formation')]});
D('hooter',{etymology:E('Hooter is formed from hoot plus -er, which can name a source of a sound. It means a horn or, in informal slang, a person’s nose.','hooter'),contexts:[C('hooter.s1','校园日常','The old ferry’s hooter sounded once before the vessel eased away from the pier.','旧渡船离开码头前鸣响了一次汽笛。','The old ferry’s hooter sounded once / before the vessel eased away / from the pier.','hooter 在此指船只发出警示声的汽笛。','渡船汽笛鸣响提醒附近的人注意。')],mistakes:[M('The mechanic called the silent steering wheel the ferry’s hooter.','The mechanic called the ferry’s warning horn its hooter.','hooter 指汽笛或喇叭，不是方向盘。')],quiz:[Q('hooter',1,1,'A ferry hooter is a?','horn that makes a warning sound','place to grow berries','unit of engine power','horn that makes a warning sound','hooter 可指汽笛或喇叭。'),Q('hooter',2,1,'Informally, someone’s hooter may mean their?','nose','heel','house','nose','口语中 hooter 可指鼻子。'),Q('hooter',3,1,'The suffix -er in hooter can identify?','a source or maker of a sound','a condition without hope','a point where sky meets sea','a source or maker of a sound','-er 可表示发出声音的设备或事物。','word-formation'),Q('hooter',4,1,'Which sentence uses hooter for a horn?','The ship sounded its hooter before leaving.','She pinched her hooter and wiped her nose.','The hooter inherited the estate.','The ship sounded its hooter before leaving.','船只离港前鸣笛使用的是汽笛义。')]});
D('hoover',{etymology:E('Hoover comes from the Hoover brand name for vacuum cleaners and became a verb in some varieties of English. To hoover means to clean a floor or surface with a vacuum cleaner.','hoover'),contexts:[C('hoover.s1','家庭清洁','Before the guests arrived, Nia hoovered the rug to remove the crumbs left after breakfast.','客人到来前，妮娅用吸尘器清理地毯，吸走早餐后留下的碎屑。','Before the guests arrived / Nia hoovered the rug / to remove the crumbs / left after breakfast.','hoover 在此作动词，表示用吸尘器清洁。','吸走地毯碎屑是吸尘器清洁行为。')],mistakes:[M('Nia hoovered the rug by pouring water over it and scrubbing it with a wet sponge.','Nia hoovered the rug with a vacuum cleaner to remove dry crumbs.','hoover 指用吸尘器清洁，不是用水冲洗。')],quiz:[Q('hoover',1,1,'To hoover a carpet is to?','clean it with a vacuum cleaner','hang it on a hook','water it with a hose','clean it with a vacuum cleaner','hoover 作动词表示用吸尘器清洁。'),Q('hoover',2,1,'Which item might someone hoover up?','dry crumbs from a rug','a family title','a hornbill’s casque','dry crumbs from a rug','吸尘器可以吸走地毯上的干碎屑。'),Q('hoover',3,1,'Hoover as a cleaning verb originated from?','a vacuum-cleaner brand name','the Latin word for hour','an Old English word for house','a vacuum-cleaner brand name','该动词来自吸尘器品牌名。','word-formation'),Q('hoover',4,1,'Which instruction uses hoover correctly?','Hoover the rug before the visitors come.','Hoover the dog’s hoof to make it run.','Hoover the letter to attach it to the email.','Hoover the rug before the visitors come.','吸尘器清理地毯是自然搭配。')]});
D('hop',{etymology:E('Hop comes from Old English hoppian, “to leap or dance.” It can mean jumping on one leg, small quick animal movements, quick short-distance travel, a short jump or flight stage, and a plant used to flavor beer.','hop'),contexts:[C('hop.s1','康复训练','During the final exercise, the therapist asked Jo to hop gently on one leg and stop if the movement caused pain.','最后一项练习中，治疗师让乔轻轻单脚跳，如果动作引起疼痛就停下。','During the final exercise / the therapist asked Jo to hop gently on one leg / and stop / if the movement caused pain.','hop 在此表示单脚跳跃。','one leg 明确体现单脚跳这一动作。')],mistakes:[M('The coach asked Jo to hop by keeping both feet planted firmly on the floor.','The coach asked Jo to hop by springing briefly on one foot.','双脚始终着地并非 hop 的跳跃动作。')],quiz:[Q('hop',1,1,'To hop on one leg is to?','jump using one foot','lie flat without moving','drive a herd through a gate','jump using one foot','hop 常指单脚跳。'),Q('hop',2,2,'A rabbit may hop by?','making short quick jumps','flying level with the horizon','making a loud horn sound','making short quick jumps','小动物可以用短促跳跃移动。'),Q('hop',3,4,'A short hop on a flight itinerary is?','one short stage of a journey','a plant used to flavor beer','a home cleaning task','one short stage of a journey','hop 也可指短途飞行或旅程的一段。'),Q('hop',4,5,'Brewers use hops from a plant to?','flavor beer','make a horseshoe','seal a glasshouse','flavor beer','hop 还可指用于啤酒调味的植物。')]});
D('hope',{etymology:E('Hope comes from Old English hopian, “to expect or trust.” It can mean wanting and expecting a good outcome, wishing something for another person, a feeling of expectation, or a person or thing that may bring success.','hope'),contexts:[C('hope.s3','社区项目','After the grant was approved, the volunteers felt renewed hope that the neighborhood garden could reopen in spring.','资助获批后，志愿者们重新燃起希望，期待社区花园能在春季重新开放。','After the grant was approved / the volunteers felt renewed hope / that the neighborhood garden / could reopen in spring.','hope 在此作名词，表示对好结果的期待。','志愿者期待花园重开，体现期待与愿望。')],mistakes:[M('The volunteers described hope as certainty that the garden would reopen, despite having no decision or funding.','The volunteers described hope as a positive expectation that the garden might reopen.','hope 是期待，不等于没有根据的确定保证。')],quiz:[Q('hope',1,1,'To hope for rain means to?','want and expect rain to come','be certain that rain already fell','clean a carpet with a vacuum','want and expect rain to come','hope 可表示希望某事发生。'),Q('hope',2,2,'“I hope you recover soon” expresses?','a wish for someone else’s benefit','a description of a horse’s foot','an inherited title','a wish for someone else’s benefit','hope 可表达对他人有益的愿望。'),Q('hope',3,3,'In “She lost hope,” hope is?','a feeling of expectation and desire','a curved punch','a short flight stage','a feeling of expectation and desire','hope 作名词可指希望这种感受。'),Q('hope',4,4,'“The young team is our hope” means the team may?','bring success','deceive the audience','make a warning sound','bring success','hope 还可指有望带来成功的人或事物。')]});
D('hopeful',{etymology:E('Hopeful combines hope with -ful, “full of.” It describes someone believing that a desired outcome can happen, something likely to succeed, or a person seeking a position or prize.','hopeful'),contexts:[C('hopeful.s1','求职准备','Although the interview was demanding, Lina remained hopeful because the panel asked detailed questions about her experience.','虽然面试要求很高，莉娜仍抱有希望，因为评审组详细询问了她的经验。','Although the interview was demanding / Lina remained hopeful / because the panel asked detailed questions / about her experience.','hopeful 在此形容相信期望结果有可能实现。','积极的面试反馈使她相信自己可能成功。')],mistakes:[M('Lina was hopeful that she would succeed, but she had completely given up expecting any good outcome.','Lina was hopeful because she believed a good outcome was still possible.','hopeful 表示仍相信好结果可能发生。')],quiz:[Q('hopeful',1,1,'A hopeful applicant believes that?','success is possible','failure is guaranteed','the interview is a house chore','success is possible','hopeful 表示抱有希望。'),Q('hopeful',2,2,'In a contest, the hopefuls are?','people who want and may win the prize','judges who have already won','the tools used to hang coats','people who want and may win the prize','hopeful 也可作名词，指参赛或竞选者。'),Q('hopeful',3,1,'Which situation sounds hopeful?','a project has funding and a workable plan','all support has been withdrawn','the team refuses to try','a project has funding and a workable plan','有资金和可行计划让成功更有可能。'),Q('hopeful',4,1,'Hopeful is formed from hope plus?','-ful','-less','-ish','-ful','-ful 表示充满或具有某种性质。','word-formation')]});
D('hopefulness',{etymology:E('Hopefulness is formed from hopeful plus -ness, a suffix making an abstract noun. It means the feeling or quality of being full of hope.','hopefulness'),contexts:[C('hopefulness.s1','心理描写','The counselor noticed a gradual return of hopefulness as the family began to see practical options for the move.','当这家人开始看到搬迁的可行选择时，咨询师注意到他们逐渐恢复了希望感。','The counselor noticed a gradual return of hopefulness / as the family began to see / practical options / for the move.','hopefulness 指抱有希望的感受或状态。','看到可行方案后，家人的希望感逐渐恢复。')],mistakes:[M('The report praised the team’s hopefulness even though it described them as certain that nothing could improve.','The report praised the team’s hopefulness because they believed improvement remained possible.','认为没有任何改善可能是绝望，不是 hopefulness。')],quiz:[Q('hopefulness',1,1,'Hopefulness is?','the feeling or quality of being hopeful','the act of cleaning with a vacuum','a group of people moving noisily','the feeling or quality of being hopeful','hopefulness 指满怀希望的状态。'),Q('hopefulness',2,1,'Which sentence shows hopefulness?','They still believe the damaged garden can recover.','They are certain that every effort is pointless.','They refuse to imagine any good outcome.','They still believe the damaged garden can recover.','相信花园仍可恢复体现希望感。'),Q('hopefulness',3,1,'The suffix -ness in hopefulness forms?','an abstract noun','a plural pronoun','a verb meaning deceive','an abstract noun','-ness 常把形容词变为抽象名词。','word-formation'),Q('hopefulness',4,1,'Hopefulness is closest in meaning to?','optimism','hostility','horizontal position','optimism','希望感与乐观相近。')]});
D('hopeless',{etymology:E('Hopeless combines hope with -less, “without.” It describes a situation offering no chance of success or improvement, and informally someone very bad at a particular skill.','hopeless'),contexts:[C('hopeless.s1','项目评估','The first repair plan proved hopeless because replacement parts were no longer manufactured and no compatible alternative existed.','第一份维修方案最终毫无希望，因为替换零件已停产，也找不到兼容替代品。','The first repair plan proved hopeless / because replacement parts were no longer manufactured / and no compatible alternative / existed.','hopeless 在此表示没有成功或改善的可能。','零件停产且没有替代品，使维修方案没有可行希望。')],mistakes:[M('The engineer called the repair hopeless even though a compatible part had just arrived and the machine worked again.','The engineer called the repair promising after the compatible part arrived and the machine worked.','已有兼容零件并成功修好，不符合 hopeless。')],quiz:[Q('hopeless',1,1,'A hopeless plan offers?','no realistic chance of success','a guaranteed award','a comfortable place to stay','no realistic chance of success','hopeless 表示没有成功可能。'),Q('hopeless',2,2,'“I am hopeless at chess” informally means?','I am extremely bad at chess','I am certain to win','I am deeply interested in chess','I am extremely bad at chess','hopeless 也可非正式地表示某项技能很差。'),Q('hopeless',3,1,'Which situation is hopeless?','every route is blocked and no alternative exists','a new route has just opened','the team has ample time and help','every route is blocked and no alternative exists','没有路线且无替代方案，难有成功希望。'),Q('hopeless',4,1,'The suffix -less means?','without','full of','in a horizontal direction','without','-less 表示缺少或没有。','word-formation')]});
D('hopelessness',{etymology:E('Hopelessness is formed from hopeless plus -ness, an abstract-noun suffix. It means the feeling or condition of having no hope.','hopelessness'),contexts:[C('hopelessness.s1','小说阅读','The novel conveys the villagers’ hopelessness through the repeated image of a locked road and a silent radio.','小说通过反复出现的封闭道路和沉默收音机，传达村民的绝望感。','The novel conveys the villagers’ hopelessness / through the repeated image / of a locked road / and a silent radio.','hopelessness 指毫无希望的感受或状态。','道路封闭、无线电无声的意象营造出绝望感。')],mistakes:[M('The diary described hopelessness as joyful confidence that a solution was just around the corner.','The diary described hopelessness as the feeling that no solution was possible.','相信解决办法即将出现与 hopelessness 的无望感相反。')],quiz:[Q('hopelessness',1,1,'Hopelessness is a feeling of?','having no hope','being certain of success','being warmly hospitable','having no hope','hopelessness 指绝望、毫无希望。'),Q('hopelessness',2,1,'A character showing hopelessness may believe?','nothing can improve the situation','a good result is likely','a new opportunity is guaranteed','nothing can improve the situation','认为局面无法改善体现绝望。'),Q('hopelessness',3,1,'The suffix -ness turns hopeless into?','a noun naming a condition','a verb meaning to jump','a plural of hope','a noun naming a condition','-ness 把形容词变成表示状态的名词。','word-formation'),Q('hopelessness',4,1,'Which word is closest to hopelessness?','despair','hospitality','hopefulness','despair','despair（绝望）与 hopelessness 意义相近。')]});
D('hopper',{etymology:E('Hopper is formed from hop plus -er. It can name a container that narrows toward its outlet and feeds material onward, or a person, insect, or animal that moves by hopping.','hopper'),contexts:[C('hopper.s1','农场设备','The grain hopper narrowed toward a chute, allowing seed to flow steadily into the planter as the tractor moved.','谷物料斗底部向出料口收窄，使拖拉机行驶时种子能稳定流入播种机。','The grain hopper narrowed toward a chute / allowing seed to flow steadily / into the planter / as the tractor moved.','hopper 在此指底部收窄、可向下送料的容器。','谷物从料斗经出料口流入播种机。')],mistakes:[M('The farmer stored grain in a hopper with no opening or outlet for the seed to leave.','The farmer used a hopper that fed grain through an opening into the planter.','料斗需要出口才能把材料送出。')],quiz:[Q('hopper',1,1,'A grain hopper is?','a container that feeds grain through a lower outlet','a tool for measuring time','a device for making a loud cry','a container that feeds grain through a lower outlet','hopper 可指底部收窄的储料容器。'),Q('hopper',2,2,'A grasshopper is called a hopper because it?','moves by jumping','stores seed in a bin','hosts a public lecture','moves by jumping','s2 指会跳跃的人或动物。'),Q('hopper',3,1,'Which machine part could be a hopper?','a seed container above a planter chute','a flat wall with no opening','a saddle on a horse','a seed container above a planter chute','播种机上方的送料箱符合 hopper 的容器义。'),Q('hopper',4,1,'Hopper is related to which verb?','hop','host','hope','hop','hopper 由 hop 加 -er 构成。','word-formation')]});
D('horde',{etymology:E('Horde came through French from Turkic or Mongolian words for a camp or tribal group. It names a large moving group of people or animals, and can be used as a verb for advancing in a large noisy crowd.','horde'),contexts:[C('horde.s1','节庆报道','A horde of visitors poured through the gates when the free exhibition opened, so staff directed people toward the quieter entrance.','免费展览开放时，大批游客涌过大门，因此工作人员把人群引向较安静的入口。','A horde of visitors poured through the gates / when the free exhibition opened / so staff directed people / toward the quieter entrance.','horde 在此指大量聚集、移动的人群。','游客成群涌入展览入口，符合大群人义。')],mistakes:[M('The report called a single visitor standing alone a horde.','The report called the large crowd of visitors a horde.','horde 指大群人或动物，不能指独自一人。')],quiz:[Q('horde',1,1,'A horde of visitors is?','a very large crowd of visitors','one person waiting alone','a small fixed payment','a very large crowd of visitors','horde 指一大群人或动物。'),Q('horde',2,2,'In historical writing, a horde can refer to?','a wandering tribal group','a single family heir','a plant used in brewing','a wandering tribal group','s2 指历史上的游牧部族群体。'),Q('horde',3,3,'To horde toward the exit means to?','advance together in a large noisy crowd','walk quietly one by one','hang coats on hooks','advance together in a large noisy crowd','horde 作动词可描述人群成群向前涌动。'),Q('horde',4,1,'Which phrase uses horde as a noun?','a horde of migrating animals','they horde the announcement yesterday','the horde is an adjective only','a horde of migrating animals','a horde of 是名词用法。','grammar')]});
D('horizon',{etymology:E('Horizon came through Latin from Greek horizōn, “bounding or limiting.” It names the apparent line where earth or sea meets sky, a limit of knowledge or experience, or something about to appear.','horizon'),contexts:[C('horizon.s1','海岸观察','At sunset, the fishing boat became a dark speck on the horizon where the sea seemed to meet the sky.','日落时，渔船在海平线上变成一个黑点；海面仿佛在那里与天空相接。','At sunset / the fishing boat became a dark speck / on the horizon / where the sea seemed to meet the sky.','horizon 在此指海天相接的视线边界。','船影出现在海面与天空仿佛相交的位置。')],mistakes:[M('The observer said the horizon was the point directly beneath her feet inside the boat.','The observer used horizon for the distant line where sea and sky appeared to meet.','视野中的 horizon 在远处，不在观察者脚下。')],quiz:[Q('horizon',1,1,'The horizon is the apparent line where?','earth or sea meets the sky','a horse’s foot meets the ground','a house meets its furniture','earth or sea meets the sky','horizon 指地平线或海平线。'),Q('horizon',2,2,'A person’s intellectual horizon is their?','limit of knowledge or experience','height above sea level only','set of household dishes','limit of knowledge or experience','s2 比喻知识或经验的范围。'),Q('horizon',3,3,'“New opportunities are on the horizon” means they are?','likely to appear soon','already forgotten','located below the ground','likely to appear soon','s3 表示即将出现或发生的事。'),Q('horizon',4,1,'Which image shows the physical horizon?','the distant line where a lake seems to meet the sky','the floor under a desk','a curved fishhook','the distant line where a lake seems to meet the sky','湖面与天空仿佛相接的远线是 horizon。')]});
D('horizontal',{etymology:E('Horizontal is formed from horizon with the adjective suffix -al and the suffixal form -tal. It describes something level, parallel to the horizon rather than vertical.','horizontal'),contexts:[C('horizontal.s1','施工测量','The carpenter checked that the shelf was horizontal before tightening the final bracket.','木匠拧紧最后一个托架前，先检查架板是否水平。','The carpenter checked / that the shelf was horizontal / before tightening / the final bracket.','horizontal 表示水平的、与地平线平行的。','架板平直不倾斜是水平状态。')],mistakes:[M('The carpenter called the shelf horizontal while it stood upright against the wall.','The carpenter called the shelf horizontal when it lay level from side to side.','竖直靠墙的架板不是 horizontal。')],quiz:[Q('horizontal',1,1,'A horizontal line runs?','level from side to side','straight up and down','in a circle around a point','level from side to side','horizontal 表示水平的。'),Q('horizontal',2,1,'Which surface is horizontal?','a level tabletop','a vertical flagpole','a steeply sloping roof','a level tabletop','水平桌面与地面平行。'),Q('horizontal',3,1,'Horizontal contrasts most directly with?','vertical','hopeful','hospitable','vertical','horizontal 与 vertical（垂直的）相对。'),Q('horizontal',4,1,'A carpenter checks a shelf is horizontal to ensure it is?','level','airtight','hereditary','level','检查水平是为了确认架板平直。')]});
D('horizontally',{etymology:E('Horizontally is the adverb formed from horizontal plus -ly. It describes movement or placement in a level direction rather than upward or downward.','horizontally'),contexts:[C('horizontally.s1','物理实验','The demonstration showed the puck gliding horizontally across the table before friction brought it to a stop.','演示中冰球在桌面上水平滑行，随后因摩擦而停下。','The demonstration showed the puck gliding horizontally / across the table / before friction / brought it to a stop.','horizontally 表示沿水平方向。','冰球沿桌面平行移动，而非上下运动。')],mistakes:[M('The diagram showed the arrow moving horizontally straight from the floor to the ceiling.','The diagram showed the arrow moving vertically from the floor to the ceiling.','从地板到天花板是垂直移动，不是水平移动。')],quiz:[Q('horizontally',1,1,'To move horizontally is to move?','level from side to side','straight upward','in a spiral downward','level from side to side','horizontally 表示水平地。'),Q('horizontally',2,1,'A shelf fixed horizontally should be?','level along its length','standing upright','curled into a hook','level along its length','架板沿长度方向应保持水平。'),Q('horizontally',3,1,'Which adverb describes a ball rolling across a flat floor?','horizontally','hereditarily','hospitably','horizontally','球在平地上横向滚动是水平运动。'),Q('horizontally',4,1,'Horizontally is formed from horizontal plus?','-ly','-less','-ness','-ly','-ly 常把形容词变成副词。','word-formation')]});
D('hormonal',{etymology:E('Hormonal is formed from hormone plus -al. It means relating to hormones, or caused by changes in hormone levels.','hormonal'),contexts:[C('hormonal.s2','医学科普','The article explains that hormonal changes during adolescence can affect sleep and mood, while emphasizing that experiences vary from person to person.','文章解释青春期的激素变化可能影响睡眠和情绪，同时强调每个人的经历各不相同。','The article explains / that hormonal changes during adolescence / can affect sleep and mood / while emphasizing that experiences vary.','hormonal 在此形容由激素水平变化引起的。','青春期激素变化与睡眠、情绪变化有关。')],mistakes:[M('The researcher called a broken chair hormonal because a change in its color affected the room.','The researcher used hormonal for changes related to the body’s hormone levels.','家具颜色改变与激素无关。')],quiz:[Q('hormonal',1,1,'A hormonal process is?','related to hormones','related to horse equipment','a way to measure an hour','related to hormones','hormonal 指与激素有关的。'),Q('hormonal',2,2,'A hormonal change may be?','caused by a shift in hormone levels','caused by a shelf being horizontal','a fee paid for a lecture','caused by a shift in hormone levels','s2 指激素水平改变引起的。'),Q('hormonal',3,1,'Which phrase is natural?','hormonal signals in the body','a hormonal horseshoe','hormonal horizon line','hormonal signals in the body','身体内的激素信号符合用法。'),Q('hormonal',4,1,'Hormonal is formed from hormone plus?','-al','-hood','-er','-al','-al 构成相关形容词。','word-formation')]});
D('hormone',{etymology:E('Hormone was formed from Greek hormōn, “setting in motion,” based on horman, “to excite or urge on.” It names a substance produced by a gland and carried in the blood to affect other organs.','hormone'),contexts:[C('hormone.s1','生物课','The lesson describes insulin as a hormone that travels in the blood and helps regulate how the body uses glucose.','课程把胰岛素描述为一种经血液运输、帮助调节身体利用葡萄糖方式的激素。','The lesson describes insulin as a hormone / that travels in the blood / and helps regulate / how the body uses glucose.','hormone 指由腺体产生并通过血液影响身体其他部位的物质。','胰岛素在体内传递并发挥调节作用。')],mistakes:[M('The textbook called a bone hormone because it carried messages through the bloodstream.','The textbook called a gland-produced chemical carried in blood a hormone.','骨骼不是经血液传递并作用于其他器官的激素。')],quiz:[Q('hormone',1,1,'A hormone is typically?','a substance made by a gland and carried in the blood','a hard covering on a hoof','a device that cleans carpets','a substance made by a gland and carried in the blood','hormone 是腺体产生并经血液运输的物质。'),Q('hormone',2,1,'Hormones can affect?','organs elsewhere in the body','only the horizon outdoors','the spelling of a plural noun','organs elsewhere in the body','激素可影响身体其他器官。'),Q('hormone',3,1,'Which is an example of a hormone?','insulin','a horseshoe','a vacuum cleaner','insulin','胰岛素是一种激素。'),Q('hormone',4,1,'The Greek source of hormone meant roughly?','setting in motion','a group of people','a curved punch','setting in motion','该词源与促动、使运行有关。','word-formation')]});
D('horn',{etymology:E('Horn comes from Old English horn and Germanic roots. It can name an animal’s hard pointed growth, a brass instrument, a vehicle warning device, or the actions of sounding a horn or goring with one.','horn'),contexts:[C('horn.s3','道路安全','The driver sounded the horn briefly to warn a cyclist that the car was approaching from behind.','司机短促地鸣笛，提醒骑车人有汽车从后方驶来。','The driver sounded the horn briefly / to warn a cyclist / that the car was approaching / from behind.','horn 在此指车辆上的警示喇叭。','司机用喇叭发声提醒道路使用者。')],mistakes:[M('The driver sounded the horn to warn the cyclist, but the car remained completely silent.','The driver sounded the horn, producing a brief warning noise.','sound the horn 表示发出声音，不能同时说车辆完全无声。')],quiz:[Q('horn',1,1,'An animal’s horn is usually?','a hard pointed growth on its head','a soft feather on its back','a tool for watering plants','a hard pointed growth on its head','horn 可指动物头部的角。'),Q('horn',2,2,'A French horn is?','a brass musical instrument','a household cleaning task','a unit of engine power','a brass musical instrument','s2 指铜管乐器。'),Q('horn',3,3,'A car horn is used to?','make a loud warning sound','hang a coat','measure distance to the horizon','make a loud warning sound','车辆喇叭用于发出警示声。'),Q('horn',4,4,'If an animal horns another, it may?','gore or strike it with its horn','feed it grain','carry it on its back','gore or strike it with its horn','horn 作动词可表示用角顶撞。')]});
D('hornbill',{etymology:E('Hornbill combines horn with bill, the beak of a bird. The name refers to a large bird of Africa or Asia whose huge bill is often topped by a horn-like growth called a casque.','hornbill'),contexts:[C('hornbill.s1','野生动物园','The guide pointed out a hornbill in the canopy, noting its oversized bill and the casque rising above it.','向导指出树冠上的犀鸟，并介绍它的大喙以及喙上突起的盔突。','The guide pointed out a hornbill in the canopy / noting its oversized bill / and the casque / rising above it.','hornbill 指一种大型非洲或亚洲鸟类，常有巨大鸟喙和盔突。','大喙上方的盔突是犀鸟的显著特征。')],mistakes:[M('The guide identified the tiny ground-dwelling fish as a hornbill because it had no beak or wings.','The guide identified the large Asian bird with a prominent bill as a hornbill.','hornbill 是有喙和翅膀的大型鸟类，不是鱼。')],quiz:[Q('hornbill',1,1,'A hornbill is a large bird from?','Africa or Asia','the ocean floor','only the Arctic ice','Africa or Asia','hornbill 指非洲或亚洲的大型鸟类。'),Q('hornbill',2,1,'A hornbill is especially known for its?','large bill, often with a casque','short hoof and mane','long vacuum-cleaner hose','large bill, often with a casque','犀鸟以巨大的喙和盔突著称。'),Q('hornbill',3,1,'The word hornbill combines horn with?','bill, meaning a bird’s beak','bill, meaning a payment','bill, meaning a hill','bill, meaning a bird’s beak','bill 在复合词中指鸟喙。','word-formation'),Q('hornbill',4,1,'Where might a wild hornbill live?','in a forest canopy in tropical Asia','in a desk drawer','inside a sealed laboratory flask','in a forest canopy in tropical Asia','部分犀鸟生活在亚洲森林。')]});
D('horned',{etymology:E('Horned is formed from horn plus the participial adjective ending -ed. It means having one or more horns, or shaped with a curve like a horn.','horned'),contexts:[C('horned.s1','自然纪录片','The documentary follows a horned lizard as it moves across the dry ground, its small projections visible along the head and body.','纪录片跟拍一只角蜥在干燥地面上移动，头部和身体上的小突起清晰可见。','The documentary follows a horned lizard / as it moves across the dry ground / its small projections visible / along the head and body.','horned 形容带角或有角状突起的。','蜥蜴头身上的角状突起与形容词义相符。')],mistakes:[M('The field guide described the smooth, featureless animal as horned even though it had no horn-like growths.','The field guide described the animal with visible horn-like projections as horned.','没有角或角状突起的动物不适合称为 horned。')],quiz:[Q('horned',1,1,'A horned animal has?','one or more horns','no hard growths at all','a horizontal tail only','one or more horns','horned 表示有角的。'),Q('horned',2,1,'A horned shape may be?','curved like a horn','flat like a level shelf','round like a berry','curved like a horn','该词也可描述角状弯曲形状。'),Q('horned',3,1,'Which animal could be called horned?','a goat with visible horns','a fish with no projections','a smooth shell with no curve','a goat with visible horns','有角的山羊符合 horned。'),Q('horned',4,1,'Horned is formed from horn plus?','-ed','-less','-ness','-ed','-ed 可构成表示具有某特征的形容词。','word-formation')]});
D('hornet',{etymology:E('Hornet comes from Old English and Germanic words related to a large wasp. It names a large social wasp whose sting can be painful.','hornet'),contexts:[C('hornet.s1','庭院观察','A hornet circled the ripe pear tree, so the family left the fruit undisturbed and called a local pest specialist.','一只胡蜂绕着成熟的梨树飞，家人没有碰那些果子，并联系了当地虫害专家。','A hornet circled the ripe pear tree / so the family left the fruit undisturbed / and called / a local pest specialist.','hornet 指体型较大的群居胡蜂，其螫刺会造成疼痛。','绕飞果树的大型胡蜂可能有攻击性，处理时应谨慎。')],mistakes:[M('The gardener called the harmless butterfly a hornet because it had colorful wings and drank nectar.','The gardener identified the large stinging wasp as a hornet.','蝴蝶不是胡蜂，胡蜂属于会螫人的蜂类。')],quiz:[Q('hornet',1,1,'A hornet is a type of?','large social wasp','small songbird','plant with a woody stem','large social wasp','hornet 是大型群居胡蜂。'),Q('hornet',2,1,'Why should a person avoid disturbing a hornet nest?','the insects can sting painfully','the nest is a type of horseshoe','the hornet cleans floors','the insects can sting painfully','胡蜂螫刺会很痛，接近蜂巢需谨慎。'),Q('hornet',3,1,'Which insect is a hornet?','a large wasp','a moth','a grasshopper','a large wasp','胡蜂属于大型黄蜂类。'),Q('hornet',4,1,'A hornet is most likely found?','near a nest in a tree or building','inside a textbook as a noun suffix','on a horse’s hoof','near a nest in a tree or building','胡蜂在树上或建筑附近筑巢。')]});
D('horrible',{etymology:E('Horrible comes through French from Latin horribilis, from horrere, “to tremble or bristle.” It describes something causing fear or strong dislike.','horrible'),contexts:[C('horrible.s1','旅行日志','The hikers described the storm as horrible because the wind tore the tent and the trail became unsafe.','徒步者认为那场风暴非常可怕，因为大风撕裂了帐篷，山路也变得危险。','The hikers described the storm as horrible / because the wind tore the tent / and the trail / became unsafe.','horrible 表示令人恐惧或强烈厌恶的。','风暴造成破坏与危险，使人感到可怕。')],mistakes:[M('They called the calm sunny afternoon horrible even though they enjoyed the weather and had no complaint.','They called the destructive storm horrible because it caused fear and danger.','令人愉快且无害的天气不符合 horrible 的负面含义。')],quiz:[Q('horrible',1,1,'A horrible event causes?','fear or strong dislike','quiet confidence','a sense of welcome','fear or strong dislike','horrible 表示可怕或令人厌恶的。'),Q('horrible',2,1,'Which scene is horrible?','a dangerous storm destroying a tent','a calm picnic in warm sunshine','a courteous welcome at a hotel','a dangerous storm destroying a tent','危险并造成破坏的风暴令人害怕。'),Q('horrible',3,1,'Horrible is closest to?','awful','hopeful','horizontal','awful','awful 与 horrible 意思相近。'),Q('horrible',4,1,'A horrible smell would likely be?','very unpleasant','pleasantly mild','a unit of power','very unpleasant','horrible 也可表示令人强烈不悦。')]});
D('horrify',{etymology:E('Horrify is formed from horrible with the verb-forming suffix -fy, ultimately from Latin horrere, “to tremble or bristle.” It means to shock someone badly or fill them with horror.','horrify'),contexts:[C('horrify.s1','新闻阅读','The account of the unsafe bridge horrified residents, who had used it daily without knowing that its supports were cracked.','关于桥梁不安全的报道让居民震惊；他们每天都走这座桥，却不知道支撑结构已经开裂。','The account of the unsafe bridge horrified residents / who had used it daily / without knowing / that its supports were cracked.','horrify 表示使某人极为震惊或恐惧。','居民得知常走的桥梁有裂缝后受到强烈惊吓。')],mistakes:[M('The discovery horrified the team, but everyone remained completely unsurprised and unconcerned.','The discovery horrified the team and left them deeply shocked.','horrify 表示强烈震惊，与毫不在意相矛盾。')],quiz:[Q('horrify',1,1,'To horrify someone is to?','shock or frighten them badly','welcome them as an honored guest','move them horizontally','shock or frighten them badly','horrify 表示使震惊或恐惧。'),Q('horrify',2,1,'What might horrify residents?','learning that their bridge has dangerous cracks','hearing that a festival opens on time','finding their lost house key','learning that their bridge has dangerous cracks','发现桥梁存在危险裂缝会令人震惊。'),Q('horrify',3,1,'Which sentence uses horrify correctly?','The graphic report horrified the readers.','The pleasant tea horrified the guest with its perfect taste.','The shelf horrified horizontally along the wall.','The graphic report horrified the readers.','令人震惊的报道可以使读者 horrify。'),Q('horrify',4,1,'The ending -fy in horrify helps form a?','verb meaning to cause a state','plural noun','directional adverb','verb meaning to cause a state','-fy 常构成表示使得、造成的动词。','word-formation')]});
D('horror',{etymology:E('Horror comes from Latin horror, “a trembling or shuddering,” from horrere, “to tremble.” It can mean intense fear or shock, something frightening or very unpleasant, or the genre of frightening stories and films.','horror'),contexts:[C('horror.s4','电影评论','The festival’s horror program pairs a quiet ghost story with a modern film about an isolated research station.','电影节的恐怖片单把一部安静的鬼故事与一部关于偏远研究站的现代影片并列放映。','The festival’s horror program / pairs a quiet ghost story / with a modern film / about an isolated research station.','horror 在此指以制造恐惧为特色的电影类型。','影展单元收录鬼故事和惊悚影片，属于恐怖片类型。')],mistakes:[M('The festival labeled its cheerful romantic comedy the horror genre, although it contained no frightening material.','The festival labeled the frightening ghost story as part of the horror genre.','没有恐怖内容的轻松爱情喜剧不属于 horror 类型。')],quiz:[Q('horror',1,1,'Horror can mean a strong feeling of?','fear and shock','hope and confidence','hospitality to guests','fear and shock','horror 可指强烈恐惧和震惊。'),Q('horror',2,2,'A horror is also something that?','causes great fear','measures an hour','feeds grain into a machine','causes great fear','s2 可指令人极度恐惧的事物。'),Q('horror',3,3,'Calling a meal “a horror” means it was?','very unpleasant','quietly hopeful','full of respect','very unpleasant','s3 可表示极其糟糕或令人厌恶的东西。'),Q('horror',4,4,'A horror film belongs to a genre meant to?','frighten its audience','teach gardening skills','show a horse race','frighten its audience','恐怖片旨在营造恐惧。')]});
D('horse',{etymology:E('Horse comes from Old English hors. It names the large riding animal and also horse riding or racing, a gymnastic apparatus or support, and rough playful behavior called horseplay.','horse'),contexts:[C('horse.s1','牧场参观','The guide led the visitors to a quiet horse in the paddock and explained how the stable staff cared for it.','向导带游客去围场看一匹安静的马，并介绍马厩工作人员如何照料它。','The guide led the visitors / to a quiet horse in the paddock / and explained / how the stable staff cared for it.','horse 在此指供骑乘的大型四足动物。','马在围场中由马厩人员照料。')],mistakes:[M('The guide called the small fish grazing in the pond a horse.','The guide called the large four-legged riding animal a horse.','鱼不是 horse 所指的马类动物。')],quiz:[Q('horse',1,1,'A horse is a large animal commonly used for?','riding','making a warning sound','cleaning a rug','riding','horse 常指可供骑乘的大型动物。'),Q('horse',2,2,'“She follows horse” may refer to?','horse riding or racing as a sport','a bird’s beak','a household chore','horse riding or racing as a sport','s2 可指马术或赛马运动。'),Q('horse',3,3,'In gymnastics, a horse can be?','an apparatus used for exercises','a payment for a lecture','a loud crowd','an apparatus used for exercises','s3 指体操器械或支撑架。'),Q('horse',4,4,'Horseplay means?','rough joking or playful behavior','formal hospitality','an inherited trait','rough joking or playful behavior','s4 指打闹嬉戏。')]});
D('horseback',{etymology:E('Horseback combines horse with back. It can name the part of a horse where a rider sits and, in the phrase on horseback, mean while riding a horse.','horseback'),contexts:[C('horseback.s2','乡间出行','The ranger crossed the open meadow on horseback because the narrow trail was too rough for a vehicle.','由于小径太崎岖，不适合车辆通行，护林员骑马穿过了开阔草地。','The ranger crossed the open meadow / on horseback / because the narrow trail / was too rough for a vehicle.','on horseback 表示骑在马背上、骑马。','护林员骑马穿过草地，符合副词短语义。')],mistakes:[M('The ranger traveled on horseback while riding entirely inside a bus.','The ranger traveled on horseback while sitting on a horse.','on horseback 表示骑马，不是乘坐公交车。')],quiz:[Q('horseback',1,1,'The horseback is the part of a horse where?','a rider sits','the hoof touches the ground','the horn makes a sound','a rider sits','horseback 可指骑手坐在马上的背部。'),Q('horseback',2,2,'To travel on horseback is to travel?','while riding a horse','inside a train','by walking on foot','while riding a horse','on horseback 表示骑马。'),Q('horseback',3,2,'Which sentence uses horseback correctly?','They rode horseback across the plain.','They parked the car on horseback.','The horsebacks the rider across the field.','They rode horseback across the plain.','骑马穿越平原可用 ride horseback。'),Q('horseback',4,1,'Horseback combines horse with?','back','bill','power','back','该词由 horse 与 back 构成。','word-formation')]});
D('horsefly',{etymology:E('Horsefly combines horse with fly. It names a stout biting fly; females of many species feed on the blood of large animals, including horses.','horsefly'),contexts:[C('horsefly.s1','牧场防虫','The horsefly landed near the mare’s eye, so the handler gently moved the horse into the screened stable.','马蝇落在母马眼睛附近，饲养员便轻轻把马牵进有纱网的马厩。','The horsefly landed near the mare’s eye / so the handler gently moved the horse / into the screened stable.','horsefly 指会叮咬的大型虻类。','马蝇落在马身上，饲养员将马移到有防护的马厩。')],mistakes:[M('The field guide called a harmless beetle that never bites a horsefly.','The field guide identified the stout blood-feeding fly as a horsefly.','horsefly 是会叮咬的虻类，不是无害甲虫。')],quiz:[Q('horsefly',1,1,'A horsefly is a type of?','stout biting fly','small domesticated horse','brass instrument','stout biting fly','horsefly 是一种体型较大的会叮咬的蝇。'),Q('horsefly',2,1,'Female horseflies often feed on?','blood of large animals','grain in a hopper','leaves only','blood of large animals','许多雌性马蝇会吸食大型动物的血液。'),Q('horsefly',3,1,'Where might a horsefly bother an animal?','around a horse in a pasture','inside a sealed document','at the horizon line','around a horse in a pasture','马蝇会在牧场附近叮咬马匹。'),Q('horsefly',4,1,'Horsefly combines horse with?','fly','herd','horror','fly','该复合词由 horse 与 fly 组成。','word-formation')]});
D('horseman',{etymology:E('Horseman combines horse with man. It traditionally means a man who rides a horse, especially as a skilled rider.','horseman'),contexts:[C('horseman.s1','历史展览','The exhibit shows a horseman crossing the valley, with his reins held loosely as the horse follows the trail.','展览展示一名骑手穿越山谷，他轻松握着缰绳，让马沿着小径前行。','The exhibit shows a horseman crossing the valley / with his reins held loosely / as the horse / follows the trail.','horseman 指骑马的男子或骑手。','人物骑在马背上并控制缰绳，符合该词义。')],mistakes:[M('The caption called a person who drove a wagon without riding a horse a horseman.','The caption called the mounted rider a horseman.','horseman 指骑在马上的人，而不只是驾车者。')],quiz:[Q('horseman',1,1,'A horseman is a man who?','rides a horse','tends a greenhouse','hosts a hotel','rides a horse','horseman 指骑马的人。'),Q('horseman',2,1,'Which person is a horseman?','a rider mounted on a horse','a driver seated in a car','a visitor at a hotel','a rider mounted on a horse','骑在马上的男子符合 horseman。'),Q('horseman',3,1,'Horseman combines?','horse + man','horror + man','house + moon','horse + man','该词由 horse 与 man 组成。','word-formation'),Q('horseman',4,1,'A skilled horseman would likely know how to handle?','reins while riding','a grain hopper','a laboratory hormone','reins while riding','骑手通常需要控制缰绳。')]});
D('horsepower',{etymology:E('Horsepower was coined by James Watt in the eighteenth century as a unit for comparing the power of steam engines with that of horses. It is about 746 watts and can also mean an engine’s power output.','horsepower'),contexts:[C('horsepower.s1','汽车说明','The compact motor produces 120 horsepower, a measure that helps compare its power with that of other engines.','这台小型发动机输出 120 马力，这一单位有助于比较它与其他发动机的功率。','The compact motor produces 120 horsepower / a measure / that helps compare its power / with that of other engines.','horsepower 在此指功率单位马力。','数字 120 表示发动机的功率额定值。')],mistakes:[M('The brochure listed the engine’s power as 120 horsepower, which it defined as a measure of distance in kilometers.','The brochure listed the engine’s output as 120 horsepower, a unit of power.','horsepower 测量功率，不测量距离。')],quiz:[Q('horsepower',1,1,'Horsepower is a unit of?','power','distance','temperature','power','horsepower 是功率单位。'),Q('horsepower',2,2,'In a car specification, horsepower may describe?','the power produced by the engine','the number of seats','the fuel tank’s color','the power produced by the engine','s2 指发动机产生的功率。'),Q('horsepower',3,1,'About how many watts is one mechanical horsepower?','746 watts','60 watts','7,460 kilometers','746 watts','机械马力约等于 746 瓦。'),Q('horsepower',4,1,'The unit horsepower was named by comparing engines with?','horses','hounds','hornbills','horses','该单位最初用于与马匹的做功能力作比较。','word-formation')]});
D('horseshoe',{etymology:E('Horseshoe combines horse with shoe. It names a curved metal band attached under a horse’s hoof, anything with a similar U shape, or the action of fitting horses with such shoes.','horseshoe'),contexts:[C('horseshoe.s1','马匹护理','The farrier shaped a new horseshoe to fit the pony’s hoof and checked that its edges sat evenly.','蹄铁匠为小马的蹄子制作了一块新马蹄铁，并检查边缘是否贴合均匀。','The farrier shaped a new horseshoe / to fit the pony’s hoof / and checked / that its edges sat evenly.','horseshoe 在此指钉在马蹄下的弧形金属蹄铁。','蹄铁匠将其制作成适合马蹄的形状。')],mistakes:[M('The farrier fitted the pony with a horseshoe by placing a flat paper square over its back.','The farrier fitted the pony with a curved metal horseshoe under its hoof.','马蹄铁装在蹄下，不是铺在马背上。')],quiz:[Q('horseshoe',1,1,'A horseshoe is usually?','a curved metal band fitted under a horse’s hoof','a soft saddle placed on the back','a horn used to warn drivers','a curved metal band fitted under a horse’s hoof','horseshoe 指马蹄铁。'),Q('horseshoe',2,1,'A horseshoe shape is often?','U-shaped','a straight vertical line','a round ball','U-shaped','马蹄铁常呈 U 形。'),Q('horseshoe',3,2,'To horseshoe a horse is to?','fit it with horseshoes','teach it to jump','measure its horsepower','fit it with horseshoes','该动词表示给马钉蹄铁。'),Q('horseshoe',4,1,'Who normally fits a horse’s shoes?','a farrier','a hotelkeeper','a hornbill','a farrier','蹄铁匠负责修蹄和钉蹄铁。')]});
D('horticultural',{etymology:E('Horticultural is formed from horticulture plus -al. Horticulture comes from Latin hortus, “garden,” and cultura, “cultivation.” Horticultural means connected with cultivating garden plants.','horticultural'),contexts:[C('horticultural.s1','园艺课程','The college opened a horticultural program focused on growing fruit trees, vegetables, and ornamental plants in small urban gardens.','学院开设了园艺课程，重点是在小型城市花园中种植果树、蔬菜和观赏植物。','The college opened a horticultural program / focused on growing fruit trees / vegetables / and ornamental plants in small urban gardens.','horticultural 表示与花园植物栽培有关的。','课程内容是种植果蔬和观赏植物，属于园艺领域。')],mistakes:[M('The college called a program in aircraft navigation horticultural even though it contained no plant cultivation.','The college called its garden-plant cultivation program horticultural.','航空导航与园艺栽培无关。')],quiz:[Q('horticultural',1,1,'Horticultural work is connected with?','cultivating garden plants','repairing aircraft engines','measuring time','cultivating garden plants','horticultural 指园艺栽培相关的。'),Q('horticultural',2,1,'Which is a horticultural project?','growing vegetables and flowers in a garden','designing a warning horn','cleaning a carpet','growing vegetables and flowers in a garden','种植蔬菜和花卉属于园艺项目。'),Q('horticultural',3,1,'Horticultural is the adjective related to?','horticulture','horror','horseplay','horticulture','horticultural 是 horticulture 的形容词。','word-formation'),Q('horticultural',4,1,'A horticultural society would likely discuss?','fruit trees and garden care','hostages and treaties','horsepower ratings','fruit trees and garden care','果树和花园护理属于园艺主题。')]});
D('horticulturalist',{etymology:E('Horticulturalist is formed from horticultural plus -ist, a suffix for a person associated with a field. It means an expert who cultivates fruits, vegetables, flowers, or ornamental plants.','horticulturalist'),contexts:[C('horticulturalist.s1','社区花园','The horticulturalist advised the community garden on soil preparation and suggested varieties suited to the shaded beds.','园艺专家为社区花园提供土壤准备建议，并推荐适合遮阴花床的品种。','The horticulturalist advised the community garden / on soil preparation / and suggested varieties / suited to the shaded beds.','horticulturalist 指从事园艺种植的专家。','土壤准备和品种选择是园艺专家的工作内容。')],mistakes:[M('The newspaper called a person who studies distant galaxies a horticulturalist despite no work with plants or gardens.','The newspaper called the garden-plant expert a horticulturalist.','研究星系的人不是园艺专家。')],quiz:[Q('horticulturalist',1,1,'A horticulturalist specializes in?','cultivating garden plants','hosting hotel guests','building horns','cultivating garden plants','horticulturalist 指园艺专家或种植者。'),Q('horticulturalist',2,1,'Which task fits a horticulturalist?','choosing vegetables for a shaded garden','calculating a car’s horsepower','repairing a ferry’s hooter','choosing vegetables for a shaded garden','为花园选择植物品种是园艺工作。'),Q('horticulturalist',3,1,'The suffix -ist often names?','a person in a field or practice','a type of plant disease','a direction of movement','a person in a field or practice','-ist 常指某领域的人或从业者。','word-formation'),Q('horticulturalist',4,1,'A horticulturalist might advise on?','soil and plant varieties','a courtroom hostage case','a horse’s warning horn','soil and plant varieties','土壤与植物品种是园艺专家可提供建议的事项。')]});
D('horticulture',{etymology:E('Horticulture comes from Latin hortus, “garden,” and cultura, “cultivation.” It means the practice of growing fruits, vegetables, and flowers in gardens, or the scientific study of garden plants and their care.','horticulture'),contexts:[C('horticulture.s1','学校菜园','The school’s horticulture club grows tomatoes and herbs in raised beds and records how much water each plot needs.','学校园艺社在高架花床中种植番茄和香草，并记录每块地需要多少水。','The school’s horticulture club grows tomatoes and herbs / in raised beds / and records / how much water each plot needs.','horticulture 在此指种植花园植物的实践。','学生种植蔬菜和香草，体现园艺实践。')],mistakes:[M('The club described building a car engine as horticulture, although it cultivated no plants or gardens.','The club described growing vegetables and herbs in garden beds as horticulture.','园艺指花园植物的种植与养护，不是汽车维修。')],quiz:[Q('horticulture',1,1,'Horticulture is the practice of?','growing fruits, vegetables, and flowers in gardens','training horses to race','cleaning floors with a vacuum','growing fruits, vegetables, and flowers in gardens','horticulture 指园艺种植。'),Q('horticulture',2,2,'Horticulture can also be the scientific study of?','garden plants and their care','human horsemanship only','formal document wording','garden plants and their care','s2 指对园艺植物及养护的科学研究。'),Q('horticulture',3,1,'Which activity belongs to horticulture?','cultivating roses and tomatoes','repairing an aircraft','sounding a car horn','cultivating roses and tomatoes','栽培玫瑰和番茄属于园艺。'),Q('horticulture',4,1,'Horticulture contains Latin elements associated with garden and?','cultivation','horror','a curved punch','cultivation','cultura 的词源与栽培有关。','word-formation')]});
D('hose',{etymology:E('Hose comes from Old English hosa, a covering for the leg. In modern use it can mean a flexible tube for carrying water; older usage also applied to stockings, and the verb means to wash or water with a hose.','hose'),contexts:[C('hose.s1','园艺养护','After the seedlings were planted, Mira used a garden hose to water the raised beds without flooding the paths.','幼苗种下后，米拉用花园水管给高架花床浇水，同时避免把小径淹湿。','After the seedlings were planted / Mira used a garden hose / to water the raised beds / without flooding the paths.','hose 在此指输送水的柔性管子。','水通过花园软管输送到花床。')],mistakes:[M('Mira used a garden hose to carry water, but the hose was a rigid metal shelf with no opening.','Mira used a flexible hose to carry water to the garden beds.','hose 作水管义时是可弯曲的管状物，不是架子。')],quiz:[Q('hose',1,1,'A garden hose is?','a flexible tube for carrying water','a curved metal shoe for a horse','a sealed letter attachment','a flexible tube for carrying water','hose 指输水软管。'),Q('hose',2,2,'In older usage, hose could mean?','stockings or leg coverings','a warning horn','a fee for a talk','stockings or leg coverings','s2 是旧式的长袜义。'),Q('hose',3,3,'To hose down a patio is to?','wash it using a hose','hang it on a hook','ride across it on horseback','wash it using a hose','hose 作动词可指用水管冲洗。'),Q('hose',4,1,'Which item most likely has a hose?','a sprinkler connected to a water line','a brass instrument case','a hotel room key','a sprinkler connected to a water line','洒水器可连接输水软管。')]});
D('hospitable',{etymology:E('Hospitable comes from Latin hospes, “guest or host,” through hospitabilis, “fit to receive guests.” It describes a friendly welcome or conditions that support life and growth.','hospitable'),contexts:[C('hospitable.s1','家庭拜访','The couple were hospitable to the visiting students, offering tea and a quiet place to rest after the long journey.','这对夫妇热情接待来访学生，提供茶水和安静的休息处，让他们结束长途旅程后稍作休息。','The couple were hospitable to the visiting students / offering tea / and a quiet place to rest / after the long journey.','hospitable 在此表示热情友好地接待客人。','主人提供茶水和休息地点，体现待客热情。')],mistakes:[M('The hosts were hospitable because they locked the door, refused to speak, and sent every visitor away.','The hosts were hospitable because they welcomed visitors and offered them a place to rest.','拒绝并驱赶访客与热情待客相反。')],quiz:[Q('hospitable',1,1,'A hospitable host is?','friendly and welcoming to visitors','unwilling to admit any guest','quick to lose their temper','friendly and welcoming to visitors','hospitable 表示好客、热情待人。'),Q('hospitable',2,2,'A hospitable climate for a crop offers?','good conditions for growth','no water or sunlight','a fee for public speaking','good conditions for growth','s2 形容适宜生命或生长的环境。'),Q('hospitable',3,1,'Which behavior is hospitable?','offering a traveler tea and a seat','shouting at a guest to leave','hiding all directions from visitors','offering a traveler tea and a seat','礼貌招待并提供座位体现好客。'),Q('hospitable',4,1,'Hospitable is related to the idea of?','a guest or host','a hoof or horn','a horizontal shelf','a guest or host','词源与宾客、主人相关。','word-formation')]});
D('hospital',{etymology:E('Hospital came through Old French from Latin hospitale, a place for guests or strangers, related to hospes, “guest.” It names a place or institution where people receive medical treatment, often as inpatients.','hospital'),contexts:[C('hospital.s1','公共服务','The new hospital opened a wing where residents can receive urgent treatment and stay overnight when necessary.','新医院开放了一个病区，居民可在那里接受紧急治疗，并在有需要时留院过夜。','The new hospital opened a wing / where residents can receive urgent treatment / and stay overnight / when necessary.','hospital 指提供医疗治疗的场所或住院机构。','医院提供急诊治疗并可收治病人过夜。')],mistakes:[M('The brochure called the shopping mall a hospital because it sold groceries but offered no medical care.','The brochure called the medical center a hospital because it treated patients.','没有医疗服务的商场不是医院。')],quiz:[Q('hospital',1,1,'A hospital is primarily a place for?','medical treatment','growing flowers','hosting a wedding only','medical treatment','hospital 是医疗机构。'),Q('hospital',2,2,'A hospital as an institution usually provides?','inpatient care','horse racing','a hose for every household','inpatient care','s2 强调提供住院照护的机构。'),Q('hospital',3,1,'Which worker is likely found in a hospital?','a nurse caring for patients','a farrier fitting horseshoes','a hotelkeeper checking guests in','a nurse caring for patients','护士在医院照护病人。'),Q('hospital',4,1,'A patient may stay overnight in a hospital when?','inpatient care is needed','they are booking a holiday room','they are watering a garden','inpatient care is needed','需要住院照护时，病人可能留院过夜。')]});
D('hospitality',{etymology:E('Hospitality comes through Old French and Latin from hospes, “guest or host.” It means generous and friendly treatment of guests, or the business sector of hotels, restaurants, and related services.','hospitality'),contexts:[C('hospitality.s1','社区接待','The neighbors showed hospitality by welcoming the exchange students, preparing dinner, and explaining how to reach the bus stop.','邻居们热情接待交换生，为他们准备晚餐，并说明如何前往公交车站。','The neighbors showed hospitality / by welcoming the exchange students / preparing dinner / and explaining how to reach the bus stop.','hospitality 在此指对访客慷慨友好的接待。','迎接、备餐并提供帮助体现待客之道。')],mistakes:[M('The host showed hospitality by ignoring the guests, serving nothing, and refusing to answer questions.','The host showed hospitality by welcoming the guests and helping them settle in.','冷落来客并拒绝帮助，不是友好接待。')],quiz:[Q('hospitality',1,1,'Hospitality means?','friendly and generous treatment of guests','the act of intimidating a visitor','a measure of engine power','friendly and generous treatment of guests','hospitality 指热情好客或待客之道。'),Q('hospitality',2,2,'The hospitality industry includes?','hotels and restaurants','only hospitals and clinics','farriers and horse races','hotels and restaurants','s2 指酒店、餐饮等服务行业。'),Q('hospitality',3,1,'Which is an example of hospitality?','welcoming a traveler and helping them find a room','sending visitors away without speaking','locking a guest outside','welcoming a traveler and helping them find a room','接待旅客并协助安排住宿是好客。'),Q('hospitality',4,1,'Hospitality is historically connected with?','guests and hosts','horsemanship','household tools','guests and hosts','词源与客人及主人相关。','word-formation')]});
D('hospitalize',{etymology:E('Hospitalize is formed from hospital with the verb suffix -ize. It means to admit or send someone to a hospital for treatment.','hospitalize'),contexts:[C('hospitalize.s1','急救记录','The clinic decided to hospitalize the cyclist for observation after the collision, even though the initial examination found no fracture.','碰撞后，诊所决定让骑车人住院观察，尽管初步检查没有发现骨折。','The clinic decided to hospitalize the cyclist / for observation after the collision / even though the initial examination / found no fracture.','hospitalize 表示将某人送入医院或收治住院。','因碰撞后需要观察而收治病人。')],mistakes:[M('The clinic hospitalized the cyclist by sending him home with no medical evaluation or hospital admission.','The clinic hospitalized the cyclist by admitting him for observation.','回家且未收治不算住院。')],quiz:[Q('hospitalize',1,1,'To hospitalize someone is to?','admit or send them to a hospital','invite them to a hotel party','teach them to ride horseback','admit or send them to a hospital','hospitalize 表示送医或收治住院。'),Q('hospitalize',2,1,'A person might be hospitalized for?','treatment or observation','watering a garden','receiving an honorary title','treatment or observation','医院可能为治疗或观察而收治病人。'),Q('hospitalize',3,1,'Which sentence uses hospitalize correctly?','Doctors hospitalized the patient overnight.','The host hospitalized a dinner party at home.','The rider hospitalized the horse over a fence.','Doctors hospitalized the patient overnight.','医生让病人住院过夜符合该动词用法。'),Q('hospitalize',4,1,'Hospitalize is formed from hospital plus?','-ize','-hood','-less','-ize','-ize 构成表示使进入某状态或过程的动词。','word-formation')]});
D('host',{etymology:E('Host comes through French from Latin hospes, “guest or host.” It can mean a person receiving guests, a presenter, an organism or computer supporting another, the act of presenting an event, or a large number.','host'),contexts:[C('host.s4','播客制作','The journalist will host a live interview program and introduce each guest before the audience questions begin.','这名记者将主持一档现场访谈节目，并在观众提问开始前介绍每位嘉宾。','The journalist will host a live interview program / and introduce each guest / before the audience questions begin.','host 在此作动词，表示主持节目。','介绍嘉宾并主持访谈是 host a program。')],mistakes:[M('The journalist hosted the live program by refusing to introduce guests and leaving the studio before it began.','The journalist hosted the live program by introducing the guests and guiding the discussion.','主持节目需要承担引导和呈现工作，而不是缺席。')],quiz:[Q('host',1,1,'A host at a dinner is the person who?','invites or receives guests','is held as a bargaining chip','cleans floors with a vacuum','invites or receives guests','host 可指招待客人的主人。'),Q('host',2,2,'A TV host usually?','introduces and presents a program','is a person kept prisoner','is a plant-killing chemical','introduces and presents a program','s2 指电视或广播节目主持人。'),Q('host',3,3,'In biology, a host organism is one that?','supports another organism living on or in it','has a hard hoof','welcomes a television audience','supports another organism living on or in it','s3 指供其他生物寄生或依附的宿主。'),Q('host',4,5,'“A host of problems” means?','a large number of problems','one guest at a dinner','a single television presenter','a large number of problems','a host of 表示大量。')]});
D('hostage',{etymology:E('Hostage came through French from medieval Latin obsidaticum, a person held as security. It names someone kept prisoner until demands are met, or something held as a guarantee or bargaining chip.','hostage'),contexts:[C('hostage.s1','新闻报道','Negotiators worked for hours to secure the release of the hostage, who had been held in a locked room during the robbery.','谈判人员努力数小时以确保人质获释；抢劫期间，此人一直被关在上锁的房间里。','Negotiators worked for hours / to secure the release of the hostage / who had been held / in a locked room during the robbery.','hostage 在此指被扣押、用来迫使他人满足条件的人。','被关押并等待谈判释放的人是人质。')],mistakes:[M('The report called a free visitor chatting in the lobby a hostage, although no one restricted the visitor’s movement.','The report called the person held prisoner during the robbery a hostage.','自由来访者没有被扣押，不能称为人质。')],quiz:[Q('hostage',1,1,'A hostage is a person who is?','held prisoner until conditions are met','welcomed as a guest','paid to give a lecture','held prisoner until conditions are met','hostage 指被扣押的人质。'),Q('hostage',2,2,'A company’s assets held as a hostage may be?','used as security or bargaining leverage','a group of hotel guests','a horse’s hoof covering','used as security or bargaining leverage','s2 可比喻被用作担保或谈判筹码的事物。'),Q('hostage',3,1,'Which situation involves a hostage?','someone held until negotiators meet a demand','a guest checking into a hostel','a cyclist visiting a hospital','someone held until negotiators meet a demand','以满足条件为由扣押某人是人质情形。'),Q('hostage',4,1,'A hostage is most directly connected with?','captivity and demands','gardening and cultivation','a horizontal surface','captivity and demands','人质通常涉及拘禁和条件要求。')]});
D('hostel',{etymology:E('Hostel comes through Old French hostel from Latin hospitale, a place for guests, related to hospes, “guest.” It means an inexpensive place to stay, often with shared facilities.','hostel'),contexts:[C('hostel.s1','背包旅行','The students booked a hostel near the station, choosing a shared dormitory to keep the trip within their budget.','学生们预订了车站附近的一家旅舍，选择共享宿舍以控制旅行开支。','The students booked a hostel near the station / choosing a shared dormitory / to keep the trip / within their budget.','hostel 指价格较低、常设共用设施的住宿处。','共享宿舍帮助学生以较低成本过夜。')],mistakes:[M('The students booked a hostel, a private hospital ward where they would receive surgery.','The students booked a hostel, an inexpensive place to stay while traveling.','hostel 是旅舍，不是医院病房。')],quiz:[Q('hostel',1,1,'A hostel is generally?','an inexpensive place to stay','a medical center for surgery','a device that measures power','an inexpensive place to stay','hostel 指旅舍或廉价住宿处。'),Q('hostel',2,1,'A traveler might choose a hostel to?','save money with shared facilities','receive inpatient treatment','buy a horseshoe','save money with shared facilities','旅舍常以共享设施降低住宿成本。'),Q('hostel',3,1,'Which sentence uses hostel correctly?','We stayed in a hostel near the train station.','The doctor hostelized the patient.','She wore a hostel on her foot.','We stayed in a hostel near the train station.','在车站附近住旅舍是自然用法。'),Q('hostel',4,1,'A hostel most often serves?','travelers needing low-cost accommodation','people seeking a brass instrument','plants growing in a hothouse','travelers needing low-cost accommodation','旅舍主要为旅客提供住宿。')]});
D('hostess',{etymology:E('Hostess is formed from host with the feminine suffix -ess. It means a woman who receives or entertains guests. In current usage, host is often used for any gender.','hostess'),contexts:[C('hostess.s1','餐厅接待','The hostess greeted the arriving diners and showed them to the table they had reserved.','女接待员迎接到店的食客，并把他们带到预订的餐桌旁。','The hostess greeted the arriving diners / and showed them / to the table / they had reserved.','hostess 指接待或招待客人的女性。','迎宾并安排客人入座体现接待工作。')],mistakes:[M('The caption called a woman hostess because she drove a tractor, although she was not receiving or entertaining guests.','The caption called the woman welcoming restaurant guests a hostess.','hostess 的该义与接待客人有关，不是泛指任何女性。')],quiz:[Q('hostess',1,1,'A hostess is traditionally a woman who?','receives or entertains guests','fits shoes on horses','measures hormone levels','receives or entertains guests','hostess 指女主人或女接待员。'),Q('hostess',2,1,'What might a restaurant hostess do?','greet diners and show them to a table','perform surgery','clean a rug with a vacuum','greet diners and show them to a table','餐厅接待员迎接顾客并安排座位。'),Q('hostess',3,1,'Hostess is formed from host plus?','-ess','-less','-ly','-ess','-ess 是传统女性后缀。','word-formation'),Q('hostess',4,1,'In many modern settings, which word can be used for any gender?','host','hostess only','horseman','host','现代用法常用 host 指任何性别的主持人或主人。')]});
D('hostile',{etymology:E('Hostile comes from Latin hostilis, “of an enemy,” from hostis, “enemy.” It describes unfriendly opposition, strongly opposed views, an environment unsuited to life, or an aggressive business takeover.','hostile'),contexts:[C('hostile.s3','野外考察','The survey team carried extra water because the desert was a hostile environment for seedlings and other fragile plants.','调查队携带了额外的水，因为沙漠环境不利于幼苗和其他脆弱植物生存。','The survey team carried extra water / because the desert was a hostile environment / for seedlings / and other fragile plants.','hostile 在此表示不利于生存或生长的。','缺水的沙漠环境不适合脆弱幼苗生长。')],mistakes:[M('The botanist called a moist greenhouse hostile to seedlings even though the plants grew rapidly there.','The botanist called the dry, waterless desert hostile to seedlings.','幼苗生长良好的温室不是不利环境。')],quiz:[Q('hostile',1,1,'A hostile person is?','unfriendly and showing opposition','warmly welcoming every visitor','unable to stop reading a novel','unfriendly and showing opposition','hostile 常表示不友好、敌对的。'),Q('hostile',2,2,'A hostile reaction is?','strongly opposed','pleasantly hospitable','a type of fruit','strongly opposed','s2 指强烈反对的意见或反应。'),Q('hostile',3,3,'A hostile climate for plants is?','difficult or unsuitable for their growth','ideal for every species','a hotel industry','difficult or unsuitable for their growth','s3 表示不适宜生长的环境。'),Q('hostile',4,4,'A hostile takeover is an acquisition that is?','unwanted and aggressively pursued','welcomed by the target company','a type of guest reception','unwanted and aggressively pursued','s4 指不受欢迎且带攻击性的企业收购。')]});
D('hostility',{etymology:E('Hostility comes from Latin hostilitas, based on hostilis, “of an enemy.” It means angry opposition or unfriendly antagonism.','hostility'),contexts:[C('hostility.s1','外交报道','The mediator asked both delegations to lower the hostility in their statements so that talks could continue.','调解人请双方代表降低声明中的敌意，以便谈判继续进行。','The mediator asked both delegations / to lower the hostility in their statements / so that talks / could continue.','hostility 指愤怒的对立或敌意。','调解人希望减少双方言辞中的敌对情绪。')],mistakes:[M('The delegates showed hostility by greeting each other warmly, listening carefully, and agreeing on every point.','The delegates showed hostility through angry opposition and refusal to cooperate.','友好倾听并一致同意并不表现敌意。')],quiz:[Q('hostility',1,1,'Hostility means?','angry opposition or antagonism','generous treatment of guests','a high level of hope','angry opposition or antagonism','hostility 指敌意或对立。'),Q('hostility',2,1,'Which exchange shows hostility?','the speakers accuse one another and refuse to cooperate','the speakers thank one another and find agreement','the speakers calmly share lunch','the speakers accuse one another and refuse to cooperate','互相指责并拒绝合作体现敌意。'),Q('hostility',3,1,'Hostility is most closely related to?','being hostile','being horizontal','being horticultural','being hostile','hostility 是 hostile 的名词形式。','word-formation'),Q('hostility',4,1,'A mediator may try to reduce hostility to?','help opposing sides talk','increase a plant’s growth','train a horse','help opposing sides talk','减少敌意有助于双方继续沟通。')]});
D('hot',{etymology:E('Hot comes from Old English hāt. It describes a high temperature, spicy burning taste, current popularity, or quick anger; as a verb, it can mean to become hot or more intense, as in hot up.','hot'),contexts:[C('hot.s5','比赛报道','The debate hotted up when the candidates began discussing the budget, and the moderator called for a short pause.','候选人开始讨论预算后，辩论变得激烈起来，主持人于是要求短暂停顿。','The debate hotted up / when the candidates began discussing the budget / and the moderator / called for a short pause.','hot 在短语 hot up 中作动词，表示变得更激烈。','候选人开始争论预算，辩论气氛升温。')],mistakes:[M('The debate hotted up as the candidates grew more animated, but the report said the discussion became less intense.','The debate hotted up as the candidates grew more animated and the discussion became more intense.','hot up 表示变得更激烈，不能说同时变得不激烈。')],quiz:[Q('hot',1,1,'A hot cup of tea has?','a high temperature','a sour taste only','a horizontal position','a high temperature','hot 的基本义是温度高。'),Q('hot',2,2,'A hot curry may taste?','spicy and burning','cold and bland','sweet like a berry','spicy and burning','hot 也可形容辛辣刺激。'),Q('hot',3,3,'A hot new app is?','currently very popular','physically boiling','in a hostile desert','currently very popular','hot 可指当下流行或热门的。'),Q('hot',4,4,'A hot-headed person is quick to become?','angry','sleepy','hospitable','angry','hot 可形容易怒、反应急躁。')]});
D('hot air',{etymology:E('Hot air is a figurative phrase combining hot with air. It means boastful or persuasive-sounding talk that is empty and unsupported by meaningful action or facts.','hot air'),contexts:[C('hot air.s1','竞选讨论','The residents dismissed the contractor’s promise to finish in one day as hot air because he had no workers or materials on site.','居民认为承包商一天完工的承诺只是空话，因为现场既没有工人也没有材料。','The residents dismissed the contractor’s promise / as hot air / because he had no workers / or materials on site.','hot air 指夸夸其谈但缺乏实际内容或行动的话。','承包商缺乏资源却夸口一天完工。')],mistakes:[M('The plan was called hot air even though the contractor had materials, workers, and a completed schedule.','The boast was called hot air because it had no supporting resources or plan.','有资源和进度安排支撑的承诺不属于空话。')],quiz:[Q('hot air',1,1,'Hot air in conversation means?','empty boastful talk','warm air from a heater only','a welcoming hotel service','empty boastful talk','hot air 是空话、夸夸其谈。'),Q('hot air',2,1,'Which is hot air?','promising a project with no plan or resources','reporting verified measurements','admitting that a deadline changed','promising a project with no plan or resources','没有计划与资源却作出夸口是空话。'),Q('hot air',3,1,'If a promise is dismissed as hot air, people think it is?','unsupported and unlikely to be acted on','already fully completed','a measure of engine power','unsupported and unlikely to be acted on','被当作 hot air 表示不可信、缺乏行动支持。'),Q('hot air',4,1,'Hot air is figurative because it refers to?','talk rather than literal heated air','a real horse’s breath only','an herbicide','talk rather than literal heated air','该短语比喻言辞空洞。')]});
D('hotbed',{etymology:E('Hotbed combines hot with bed. Originally it referred to a heated bed of soil for raising plants; figuratively it is a place or situation where an activity develops quickly.','hotbed'),contexts:[C('hotbed.s1','温室种植','The gardener started tomato seedlings in a hotbed, using warmth beneath the soil to encourage early growth.','园丁在温床里培育番茄幼苗，利用土壤下方的热量促进早期生长。','The gardener started tomato seedlings in a hotbed / using warmth beneath the soil / to encourage / early growth.','hotbed 在此指用于促进植物生长的温床。','土壤下方的热量帮助幼苗提早生长。')],mistakes:[M('The gardener called a frozen stone patio a hotbed for seedlings although it provided no warmth or soil.','The gardener called the warmed soil bed used for seedlings a hotbed.','没有土壤和热量的石质露台不适合称为育苗温床。')],quiz:[Q('hotbed',1,1,'A horticultural hotbed is?','a warmed bed of soil for growing plants','a place for boarding a horse','a unit of engine power','a warmed bed of soil for growing plants','hotbed 原指育苗温床。'),Q('hotbed',2,1,'A hotbed of activity is figuratively?','a place where an activity develops quickly','a place with no activity at all','a room for hospital patients','a place where an activity develops quickly','比喻义指某活动容易兴起的地方或情境。'),Q('hotbed',3,1,'Which sentence uses hotbed literally?','They used a hotbed to raise early seedlings.','The club became a hotbed of discussion.','The driver sounded the hotbed.','They used a hotbed to raise early seedlings.','育苗温床是该词的字面用法。'),Q('hotbed',4,1,'A hotbed can help seedlings by providing?','warmth','a metal hook','a horse to ride','warmth','温床以热量促进幼苗生长。')]});
D('hotdog',{etymology:E('Hotdog is an American compound of hot and dog, first used for the sausage served in a long roll. As a verb, hot-dog means to perform showy tricks, especially in sports such as surfing or skiing.','hotdog'),contexts:[C('hotdog.s1','球赛餐饮','At the baseball game, Eli bought a hotdog in a long roll and added mustard before returning to his seat.','棒球赛上，伊莱买了一份长面包夹热狗肠，涂上芥末后回到座位。','At the baseball game / Eli bought a hotdog in a long roll / and added mustard / before returning to his seat.','hotdog 在此指夹在长面包中的熟香肠。','长面包和芥末是热狗食品的常见搭配。')],mistakes:[M('The vendor served a hotdog as a cold bowl of unseasoned cereal with no sausage or roll.','The vendor served a hotdog as a cooked sausage inside a long roll.','不含香肠和长面包的冷麦片不是 hotdog。')],quiz:[Q('hotdog',1,1,'A hotdog is usually?','a cooked sausage served in a long roll','a horse’s metal shoe','a warm bed of soil','a cooked sausage served in a long roll','hotdog 指热狗食品。'),Q('hotdog',2,2,'To hotdog on skis is to?','perform showy tricks','serve food to guests','clean a carpet','perform showy tricks','s2 作动词指在运动中炫技。'),Q('hotdog',3,1,'Where might someone buy a hotdog?','at a ballpark food stand','at a farrier’s workshop','at a hospital ward','at a ballpark food stand','球场小吃摊常售卖热狗。'),Q('hotdog',4,2,'Which sentence uses hotdog as a verb?','The skier hotdogged down the slope.','She ordered a hotdog with mustard.','The hotdog was in a paper tray.','The skier hotdogged down the slope.','hotdogged 描述滑雪者炫技。','grammar')]});
D('hotel',{etymology:E('Hotel came through French hôtel from Latin hospitale, a lodging place for guests, related to hospes, “guest.” It means a building offering paid accommodation and can also be a venue for social or business events.','hotel'),contexts:[C('hotel.s1','差旅安排','The team booked a hotel near the conference center so the researchers could walk to their rooms after the evening session.','团队在会议中心附近预订了一家酒店，研究人员晚间会议结束后可以步行回房间。','The team booked a hotel near the conference center / so the researchers could walk / to their rooms / after the evening session.','hotel 在此指提供付费住宿的建筑或机构。','研究人员预订房间并在会后住宿。')],mistakes:[M('The travelers booked a hotel for the night, but the building offered no rooms or overnight accommodation.','The travelers booked a hotel that provided rooms for overnight stays.','不提供住宿的建筑不符合酒店的主要义项。')],quiz:[Q('hotel',1,1,'A hotel primarily provides?','paid accommodation','medical surgery','garden tools','paid accommodation','hotel 指提供付费住宿的场所。'),Q('hotel',2,2,'A hotel may also be used as?','a venue for social or business events','a horse’s hoof','a container for grain','a venue for social or business events','s2 指酒店也可作为活动场所。'),Q('hotel',3,1,'Which person is most likely a hotel guest?','a traveler who books a room overnight','a horse being fitted with shoes','a plant growing in soil','a traveler who books a room overnight','旅客预订房间住宿，是酒店客人。'),Q('hotel',4,1,'Hotel is historically related to a word for?','a place for guests','a horned animal','a unit of power','a place for guests','词源与接待宾客的场所相关。','word-formation')]});
D('hotelkeeper',{etymology:E('Hotelkeeper combines hotel with keeper, from keep, “manage or look after.” It means a person who manages a hotel as a business.','hotelkeeper'),contexts:[C('hotelkeeper.s1','地方史采访','The retired hotelkeeper recalled how she managed the guest register, hired staff, and arranged repairs to the old inn.','退休的旅馆经营者回忆了自己如何管理住客登记、雇用员工并安排修缮旧旅馆。','The retired hotelkeeper recalled / how she managed the guest register / hired staff / and arranged repairs to the old inn.','hotelkeeper 指经营或管理酒店的人。','管理登记、员工与维修体现旅馆经营者的职责。')],mistakes:[M('The article called a hotel guest who stayed one night the hotelkeeper, though the guest did not manage the business.','The article called the person managing the hotel the hotelkeeper.','普通住客不负责经营酒店。')],quiz:[Q('hotelkeeper',1,1,'A hotelkeeper is someone who?','manages a hotel as a business','repairs horseshoes','hosts a television news show only','manages a hotel as a business','hotelkeeper 指旅馆经营者。'),Q('hotelkeeper',2,1,'Which task fits a hotelkeeper?','organizing staff and guest records','treating patients in a hospital','cultivating tomatoes in a hotbed','organizing staff and guest records','酒店经营者管理员工和住客事务。'),Q('hotelkeeper',3,1,'Hotelkeeper combines hotel with?','keeper','horizon','hornbill','keeper','该复合词由 hotel 和 keeper 构成。','word-formation'),Q('hotelkeeper',4,1,'A hotelkeeper is different from a hotel guest because the keeper?','runs the accommodation business','only rents a room for a night','is held as a hostage','runs the accommodation business','酒店经营者负责运营，而住客只租住。')]});
D('hotheaded',{etymology:E('Hotheaded combines hot with headed. It describes someone who reacts quickly and angrily, often acting rashly before thinking.','hotheaded'),contexts:[C('hotheaded.s1','团队协作','The hotheaded player argued with the referee immediately, then regretted his words after watching the replay.','这名急躁的球员马上与裁判争吵，看到回放后又为自己的话感到后悔。','The hotheaded player argued with the referee immediately / then regretted his words / after watching / the replay.','hotheaded 指容易发怒并仓促行动的。','球员立即争吵，随后后悔，体现冲动易怒。')],mistakes:[M('The calm captain was called hotheaded even though she listened patiently and waited before responding.','The player who reacted angrily without thinking was called hotheaded.','冷静倾听并等待再回应与急躁易怒相反。')],quiz:[Q('hotheaded',1,1,'A hotheaded person is quick to?','lose their temper and act rashly','welcome strangers generously','measure the horizon','lose their temper and act rashly','hotheaded 表示易怒、冲动。'),Q('hotheaded',2,1,'Which action is hotheaded?','shouting at a referee before checking the facts','asking calmly for a replay','waiting to hear both sides','shouting at a referee before checking the facts','未查明事实就发火属于冲动行为。'),Q('hotheaded',3,1,'Hotheaded is closest in meaning to?','quick-tempered','hospitable','hopeful','quick-tempered','quick-tempered 与 hotheaded 意思相近。'),Q('hotheaded',4,1,'A hotheaded response is often made?','before thinking carefully','after a long calm review','as a formal payment','before thinking carefully','hotheaded 的行为常缺少审慎思考。')]});
D('hothouse',{etymology:E('Hothouse combines hot with house. It names a warm glass building used for growing plants, similar to a greenhouse, and can figuratively describe an intense environment for development.','hothouse'),contexts:[C('hothouse.s1','园艺生产','The nursery kept tropical seedlings in a hothouse where glass panels trapped warmth and protected the plants from cold nights.','苗圃把热带幼苗放在温室里，玻璃板留住热量并保护植物免受夜间寒冷影响。','The nursery kept tropical seedlings in a hothouse / where glass panels trapped warmth / and protected the plants / from cold nights.','hothouse 指用于栽培植物的温暖玻璃房。','玻璃板保温并防寒，适合热带幼苗生长。')],mistakes:[M('The nursery called an unheated open field a hothouse even though it had no glass walls or warmth.','The nursery called the warm glass building for plants a hothouse.','没有围护结构和热量的露天田地不是温室。')],quiz:[Q('hothouse',1,1,'A hothouse is a warm glass building for?','growing plants','keeping hotel records','hosting a news show','growing plants','hothouse 指栽培植物的温室。'),Q('hothouse',2,1,'Why are tropical plants kept in a hothouse?','it traps warmth and protects them from cold','it provides a horse with a saddle','it removes all sunlight','it traps warmth and protects them from cold','温室保温，可保护怕冷植物。'),Q('hothouse',3,1,'Which structure is a hothouse?','a glass building heated for plant growth','an open frozen field','a hotel guest room','a glass building heated for plant growth','为植物保温的玻璃建筑是 hothouse。'),Q('hothouse',4,1,'Hothouse combines hot with?','house','host','hoof','house','该复合词由 hot 和 house 组成。','word-formation')]});
D('hound',{etymology:E('Hound comes from Old English hund, “dog.” It names a dog used for hunting, can be an insult for an unpleasant person, and as a verb means to keep following or bothering someone.','hound'),contexts:[C('hound.s3','新闻采访','Reporters continued to hound the official with questions outside the station, even after she asked for time to respond.','官员请求留些时间回应后，记者仍在车站外不断追问她。','Reporters continued to hound the official with questions / outside the station / even after she asked / for time to respond.','hound 在此作动词，表示持续跟随或纠缠某人。','记者不断追问，体现反复纠缠的动词义。')],mistakes:[M('The reporters hounded the official by leaving her alone and never asking another question.','The reporters hounded the official by following her and repeatedly demanding answers.','完全不打扰对方与 hound 的纠缠义相反。')],quiz:[Q('hound',1,1,'A hunting hound is a?','dog used for hunting','large wasp','type of garden hose','dog used for hunting','hound 可指猎犬。'),Q('hound',2,2,'Calling someone a hound may insult them as?','an unpleasant or contemptible person','a generous host','a skilled gardener','an unpleasant or contemptible person','s2 是贬义称呼。'),Q('hound',3,3,'To hound a public official means to?','keep following or bothering them','welcome them to a hotel','fit them with a horseshoe','keep following or bothering them','hound 作动词表示持续追问或纠缠。'),Q('hound',4,1,'Which sentence uses hound as a verb?','The journalists hounded the singer for a comment.','A hound slept beside the fireplace.','The hound is a type of hotel.','The journalists hounded the singer for a comment.','持续追问歌手使用动词 hound。','grammar')]});
D('hour',{etymology:E('Hour came through Old French from Latin hora and Greek hōra, a time or season. It names a period of sixty minutes, a particular point on a clock, or a fixed daily period of work.','hour'),contexts:[C('hour.s1','列车时刻','The express train reaches the coastal station in just under an hour, according to the updated timetable.','根据更新后的时刻表，特快列车不到一小时就能抵达海滨车站。','The express train reaches the coastal station / in just under an hour / according to / the updated timetable.','hour 在此指六十分钟的一段时间。','“不到一小时”表示经过的时长。')],mistakes:[M('The timetable said the train would take an hour, a period of fifteen minutes.','The timetable said the train would take an hour, a period of sixty minutes.','一小时是六十分钟，不是十五分钟。')],quiz:[Q('hour',1,1,'One hour is equal to?','sixty minutes','one hundred seconds','seven days','sixty minutes','hour 指六十分钟。'),Q('hour',2,2,'“The meeting begins at the hour” may refer to?','a particular point on the clock','a group of hotel guests','a form of gardening','a particular point on the clock','s2 可指钟表上的整点或特定时刻。'),Q('hour',3,3,'A worker’s lunch hour can be?','a fixed period in the workday','a horse’s shoe','a loud confused noise','a fixed period in the workday','s3 可指每天固定的工作时段。'),Q('hour',4,1,'Which expression means a period of sixty minutes?','for an hour','for a huddle','for a huckleberry','for an hour','for an hour 表示持续一小时。')]});
D('hours',{etymology:E('Hours is the regular plural of hour, from Latin hora through French. It refers to multiple sixty-minute periods and often appears in phrases for operating times or durations.','hours'),contexts:[C('hours.s1','营业时间','The clinic’s hours are posted on the front door, and patients should call ahead before arriving after sunset.','诊所的营业时间张贴在正门上，患者日落后到达前应先打电话确认。','The clinic’s hours are posted / on the front door / and patients should call ahead / before arriving after sunset.','hours 在此指诊所开放或营业的时段。','门上张贴的 hours 告知诊所何时开放。')],mistakes:[M('The sign said the clinic’s hours were 9 to 5, but explained that hours meant only two minutes.','The sign listed the clinic’s opening hours as 9 to 5.','hours 表示时段或小时数，不是两分钟。')],quiz:[Q('hours',1,1,'The phrase opening hours tells customers?','when a business is open','how much a product costs','where a horse sleeps','when a business is open','opening hours 指营业时间。'),Q('hours',2,1,'“The repair took three hours” means it took?','three periods of sixty minutes','three days','three hounds','three periods of sixty minutes','三个小时共一百八十分钟。'),Q('hours',3,1,'Hours is the plural of?','hour','house','host','hour','hours 是 hour 的复数。','grammar'),Q('hours',4,1,'A sign showing library hours is useful for learning?','when visitors can enter','how to grow plants','how to fit a horseshoe','when visitors can enter','图书馆开放时段帮助访客安排到访。')]});
D('house',{etymology:E('House comes from Old English hūs, a dwelling or shelter. It can name a home, a building for a particular purpose, a legislative assembly, an audience or firm, and as a verb means to provide lodging or contain something.','house'),contexts:[C('house.s5','社区住房','The association will house six displaced families in vacant apartments until permanent repairs are finished.','永久修缮完成前，协会将安排六户流离失所的家庭住进空置公寓。','The association will house six displaced families / in vacant apartments / until permanent repairs / are finished.','house 在此作动词，表示为人提供住所。','协会让家庭暂住公寓，体现安置、提供住房的动词义。')],mistakes:[M('The association housed the families by leaving them outdoors without shelter or a place to stay.','The association housed the families in vacant apartments.','让人露宿户外并未提供住所。')],quiz:[Q('house',1,1,'A house is most commonly?','a building where people live','a period of sixty minutes','a flying vehicle','a building where people live','house 的常见义是住宅。'),Q('house',2,2,'The House voted on a bill means?','a legislative assembly voted','a family living room voted','a group of berries voted','a legislative assembly voted','s3 指议会或立法机构。'),Q('house',3,4,'“The house applauded” in a theater refers to?','the audience','the building materials','the hotel manager','the audience','s4 可指剧院观众。'),Q('house',4,5,'To house refugees means to?','provide them with a place to live','deceive them','ask them to host a show','provide them with a place to live','house 作动词表示安置或提供住所。')]});
D('household',{etymology:E('Household combines house with hold, historically referring to the people and servants of a home. It can mean everyone living together in a home, describe matters related to running a home, or something familiar to everyone.','household'),contexts:[C('household.s1','人口调查','The survey counts each household once, including everyone who usually lives at the same address.','调查按户统计，每个住址通常居住的所有人计为一个家庭住户。','The survey counts each household once / including everyone / who usually lives / at the same address.','household 在此指住在同一家庭或住所的一群人。','问卷按共同居住者统计住户。')],mistakes:[M('The survey counted a household as one person who had never lived at the listed address.','The survey counted everyone usually living at the same address as one household.','household 通常包括共同居住在一个住所内的人。')],quiz:[Q('household',1,1,'A household consists of?','people living together in a home','all residents of an entire country','one item in a hotel room','people living together in a home','household 指共同居住的一户人家。'),Q('household',2,2,'Household chores are tasks related to?','running a home','growing wild berries','hosting a television show','running a home','s2 指家庭日常事务。'),Q('household',3,3,'A household name is?','known to nearly everyone','used only inside one family','a kind of garden hose','known to nearly everyone','s3 比喻家喻户晓的。'),Q('household',4,1,'Which data could describe a household?','the people sharing one home','the number of hours in a day','the power of an engine','the people sharing one home','同住人员构成住户信息。')]});
D('housekeeping',{etymology:E('Housekeeping combines house with keeping, from keep in the sense of managing or maintaining. It means domestic tasks, hotel room-cleaning work, or routine maintenance of records and systems.','housekeeping'),contexts:[C('housekeeping.s1','家庭安排','Their weekly housekeeping includes cooking, laundry, and cleaning the kitchen after dinner.','他们每周的家务包括做饭、洗衣以及晚餐后清理厨房。','Their weekly housekeeping includes cooking / laundry / and cleaning the kitchen / after dinner.','housekeeping 在此指清洁、做饭等家庭日常事务。','列举的烹饪和清洁都是家务。')],mistakes:[M('The family called repairing a spacecraft in orbit their housekeeping, although no home tasks or records were involved.','The family called cooking, laundry, and home cleaning their housekeeping.','家务义与航天器维修无关。')],quiz:[Q('housekeeping',1,1,'Housekeeping at home includes?','cleaning and cooking','training a horse','hosting a talk show','cleaning and cooking','housekeeping 指家庭清洁与日常料理。'),Q('housekeeping',2,2,'Hotel housekeeping usually involves?','cleaning guest rooms','treating patients','growing tomatoes','cleaning guest rooms','s2 指酒店客房清洁部门或工作。'),Q('housekeeping',3,2,'In computing, housekeeping may mean?','routine maintenance of records or data','a room where guests sleep','a fruit-growing science','routine maintenance of records or data','s2 也可指数据或记录的常规整理维护。'),Q('housekeeping',4,1,'Which task is household housekeeping?','washing dishes after dinner','measuring engine horsepower','making a horse neigh','washing dishes after dinner','饭后洗碗是家务之一。')]});
D('housewares',{etymology:E('Housewares combines house with wares, goods offered for sale. It names household items such as pans, dishes, and small appliances sold for home use.','housewares'),contexts:[C('housewares.s1','商店导览','The department store moved its housewares section beside the kitchen displays, grouping pans, plates, and small appliances together.','百货商店把家居用品区移到厨房展示品旁边，将锅具、餐盘和小家电放在一起。','The department store moved its housewares section / beside the kitchen displays / grouping pans, plates, / and small appliances together.','housewares 指供家庭使用的锅具、餐具和小家电等用品。','列举的厨房用品属于家居商品。')],mistakes:[M('The store labeled its industrial freight cranes housewares, although they were not ordinary goods for home use.','The store labeled its pans, dishes, and small appliances housewares.','大型工业起重机不属于日常家居用品。')],quiz:[Q('housewares',1,1,'Housewares are goods used?','in the home','only in a hospital operating room','to measure an hour','in the home','housewares 指家用物品。'),Q('housewares',2,1,'Which item is housewares?','a frying pan','a horsefly','a legislative assembly','a frying pan','煎锅是常见家居用品。'),Q('housewares',3,1,'A shop’s housewares department may sell?','dishes and small appliances','only hotel rooms','hormones','dishes and small appliances','餐具和小家电属于 housewares。'),Q('housewares',4,1,'Housewares combines house with?','wares, meaning goods for sale','hours, meaning sixty minutes','horror, meaning fear','wares, meaning goods for sale','wares 指商品。','word-formation')]});
D('housewife',{etymology:E('Housewife combines house with wife, historically naming a woman who managed domestic work. It can also refer in older usage to a small sewing kit or case for needles and thread; the domestic-role sense is dated and gendered.','housewife'),contexts:[C('housewife.s1','语言历史','In the historical novel, the housewife managed the household’s meals and supplies, reflecting the domestic role common in that period.','在这部历史小说中，家庭主妇负责安排家人的餐食和用品，反映了那个时期常见的家庭角色。','In the historical novel / the housewife managed the household’s meals and supplies / reflecting the domestic role / common in that period.','housewife 的传统义指主要管理家务的女性，现常被视为带有时代与性别色彩。','语境明确为历史时期的家庭角色。')],mistakes:[M('The modern job listing used housewife as a neutral title for every person employed as an engineer.','The historical text used housewife for a woman whose main role was managing the home.','housewife 不能作为所有职业的中性称谓，且家庭角色义带时代色彩。')],quiz:[Q('housewife',1,1,'In its traditional sense, a housewife is?','a woman whose main role is looking after her home','a person who manages a hotel','a professional horse rider','a woman whose main role is looking after her home','housewife 的传统义为家庭主妇。'),Q('housewife',2,2,'In older usage, a housewife can also be?','a small case for needles and thread','a type of horse’s hoof','a public lecture fee','a small case for needles and thread','s2 是旧式的针线盒或针线包义。'),Q('housewife',3,1,'The domestic-role meaning of housewife is often described as?','dated and gendered','a neutral scientific term','a verb meaning to huddle','dated and gendered','该义反映传统性别分工，现代语境应留意。'),Q('housewife',4,1,'Which sentence uses the older sewing-kit sense?','She packed a housewife with needles for the trip.','The housewife checked into a hotel for one night.','The housewife hounded the reporter.','She packed a housewife with needles for the trip.','携带针线包使用的是旧式义。')]});
D('housework',{etymology:E('Housework combines house with work. It means cleaning and other practical tasks done in the home, or more broadly the routine work involved in running a household.','housework'),contexts:[C('housework.s1','家庭分工','The roommates divide housework by alternating who cooks dinner, sweeps the floor, and takes out the recycling.','室友们轮流做晚饭、扫地和倒回收物，以分担家务。','The roommates divide housework / by alternating who cooks dinner / sweeps the floor / and takes out the recycling.','housework 指在家中完成的清洁及其他日常劳动。','做饭、扫地和倒回收物都是家务。')],mistakes:[M('The roommates listed flying a helicopter as their weekly housework, although it had nothing to do with running their home.','The roommates listed cooking and cleaning as their weekly housework.','驾驶直升机不是维持家庭运转的家务。')],quiz:[Q('housework',1,1,'Housework includes?','cleaning and other tasks done in a home','only paid hotel management','medical treatment','cleaning and other tasks done in a home','housework 指家庭劳动。'),Q('housework',2,1,'Which is housework?','sweeping the kitchen floor','building an engine','leading a political assembly','sweeping the kitchen floor','扫厨房地板属于家务。'),Q('housework',3,2,'Housework can broadly include?','routine tasks involved in running a household','only making a bed','only activities done outside a home','routine tasks involved in running a household','s2 涵盖家庭日常运转相关工作。'),Q('housework',4,1,'Housework combines house with?','work','wares','hostage','work','该复合词由 house 和 work 组成。','word-formation')]});
D('housing',{etymology:E('Housing is formed from house with the suffix -ing. It refers collectively to houses or other places for people to live.','housing'),contexts:[C('housing.s1','城市规划','The council approved new housing near the transit line to give more families access to affordable homes.','市议会批准在交通线路附近建设新住房，让更多家庭能够住上可负担的房屋。','The council approved new housing / near the transit line / to give more families access / to affordable homes.','housing 指供人居住的房屋或住房总体。','新建住房扩大了可负担居所的供给。')],mistakes:[M('The council called a new motorway project housing even though it created no homes or places to live.','The council called the planned homes near transit new housing.','高速公路本身不是住房。')],quiz:[Q('housing',1,1,'Housing refers to?','houses or other places for people to live','only household decorations','a unit of engine power','houses or other places for people to live','housing 指住房。'),Q('housing',2,1,'An affordable housing plan aims to provide?','homes people can reasonably pay for','hospital treatment for patients','a hotel’s entertainment program','homes people can reasonably pay for','可负担住房是人们能够承担费用的住所。'),Q('housing',3,1,'Which issue concerns housing?','the supply of apartments and homes','the sound of a horn','a horse’s diet','the supply of apartments and homes','住房供应属于 housing 议题。'),Q('housing',4,1,'Housing is based on which word?','house','hound','horizon','house','housing 由 house 派生。','word-formation')]});
D('hover',{etymology:E('Hover comes from Middle English hoveren, “to hover or linger,” probably related to a word meaning to tarry. It can mean staying in the air, waiting nearby, remaining undecided, or staying near a level or figure.','hover'),contexts:[C('hover.s1','飞行观察','The rescue helicopter hovered above the field while the crew lowered a medic on a cable.','救援直升机悬停在田地上方，机组人员用缆绳放下一名医护人员。','The rescue helicopter hovered above the field / while the crew lowered a medic / on a cable.','hover 在此表示停留在空中、悬停。','直升机在一个位置上方保持飞行。')],mistakes:[M('The helicopter hovered above the field while it remained parked in a locked hangar.','The helicopter hovered above the field while remaining airborne.','停在机库中的飞机没有悬停在空中。')],quiz:[Q('hover',1,1,'A helicopter that hovers?','stays in the air in one place','moves quickly underground','rests on a horseshoe','stays in the air in one place','hover 可指在空中悬停。'),Q('hover',2,2,'A person hovering near a doorway may be?','waiting nearby','flying in the air','measuring a hormone','waiting nearby','s2 表示在附近徘徊等待。'),Q('hover',3,3,'To hover between two choices is to?','remain uncertain which to choose','make a firm final choice','host a television show','remain uncertain which to choose','s3 比喻犹豫不决。'),Q('hover',4,4,'A price hovering around $20 is?','staying close to that figure','falling to zero immediately','a house for guests','staying close to that figure','s4 表示数值维持在某一水平附近。')]});
D('hovercraft',{etymology:E('Hovercraft combines hover with craft, “vehicle.” It names a vehicle lifted by a cushion of downward-blown air so that it can travel over land or water.','hovercraft'),contexts:[C('hovercraft.s1','交通展览','The museum’s hovercraft crossed both the shallow water and the smooth concrete demonstration track on a cushion of air.','博物馆的气垫船依靠气垫穿越浅水区和光滑的混凝土演示跑道。','The museum’s hovercraft crossed both the shallow water / and the smooth concrete demonstration track / on a cushion of air.','hovercraft 指由向下气流托起、可掠过地面或水面的交通工具。','气垫使车辆能跨越水面和陆地。')],mistakes:[M('The exhibit called an ordinary submarine a hovercraft even though it traveled underwater on propellers.','The exhibit called the air-cushion vehicle that moved over land and water a hovercraft.','水下螺旋桨潜艇不是靠气垫掠行的 hovercraft。')],quiz:[Q('hovercraft',1,1,'A hovercraft is lifted by?','a cushion of air blown downward','a horse pulling a carriage','a long underwater cable','a cushion of air blown downward','hovercraft 由向下气流形成的气垫托起。'),Q('hovercraft',2,1,'A hovercraft can travel over?','land and water','only vertical walls','the horizon itself','land and water','气垫船可越过陆地和水面。'),Q('hovercraft',3,1,'Which vehicle is a hovercraft?','an air-cushion craft that skims over a surface','a standard submarine beneath the sea','a horse-drawn wagon','an air-cushion craft that skims over a surface','气垫船依靠气垫贴近表面行驶。'),Q('hovercraft',4,1,'Hovercraft combines hover with?','craft, meaning a vehicle','house, meaning a home','hope, meaning desire','craft, meaning a vehicle','craft 在此指交通工具。','word-formation')]});
D('how',{etymology:E('How comes from Old English hū. It asks about manner or means, appears in exclamations about degree, asks about amount or degree, and can ask about someone’s health or condition.','how'),contexts:[C('how.s4','电话问候','When Ava called her grandfather, she asked how he was feeling after the long train journey.','艾娃给祖父打电话时，询问他长途火车旅行后感觉怎么样。','When Ava called her grandfather / she asked how he was feeling / after the long train journey.','how 在此用于询问某人的身体状况。','how he was feeling 询问祖父的健康或状态。')],mistakes:[M('Ava asked how her grandfather was feeling but meant to ask which platform his train used.','Ava asked how her grandfather was feeling to learn about his condition.','询问感觉或健康状况不等于询问站台。')],quiz:[Q('how',1,1,'“How did you solve it?” asks about?','the way or method','the price only','a person’s title','the way or method','s1 询问方式或方法。'),Q('how',2,2,'“How beautiful!” uses how to express?','degree or intensity','a direction of travel','a plural noun','degree or intensity','s2 用于感叹程度。'),Q('how',3,3,'“How many books?” asks about?','amount or number','health or condition','the method of riding','amount or number','s3 询问数量或程度。'),Q('how',4,4,'“How are you?” asks about someone’s?','health or condition','household goods','horsepower','health or condition','s4 询问近况或身体状态。')]});
D('how much',{etymology:E('How much combines how with much, a determiner used for uncountable quantity or price. The phrase asks about an amount or how much something costs.','how much'),contexts:[C('how much.s1','市场购物','At the market, Leo asked how much the basket of peaches cost before deciding whether to buy it.','在市场上，利奥先问那篮桃子多少钱，再决定是否购买。','At the market / Leo asked how much the basket of peaches cost / before deciding / whether to buy it.','how much 用来询问数量或价格。','句中询问一篮桃子的价格。')],mistakes:[M('Leo asked how much peaches were there, then answered with the exact number of individual peaches.','Leo asked how many peaches there were, or how much the basket cost.','可数名词 peaches 的数量通常用 how many，而价格或不可数数量用 how much。')],quiz:[Q('how much',1,1,'“How much is this basket?” asks about?','its price','the number of baskets','the traveler’s health','its price','how much 常用于询问价格。'),Q('how much',2,1,'Which noun phrase naturally follows how much?','water','apples','chairs','water','water 是不可数名词，可用 how much 询问数量。'),Q('how much',3,1,'To ask for the price of a ticket, say?','How much is the ticket?','How many is the ticket?','How on earth the ticket?','How much is the ticket?','询问价格用 how much。','grammar'),Q('how much',4,1,'How much can ask about an amount or?','cost','direction','a host','cost','该短语可询问数量或费用。')]});
D('how on earth',{etymology:E('How on earth combines how with the emphatic phrase on earth. It intensifies a question to show surprise, frustration, or disbelief.','how on earth'),contexts:[C('how on earth.s1','疑问对话','“How on earth did the keys end up inside the locked drawer?” Mara asked, still holding the only key.','玛拉仍拿着唯一的钥匙，却问：“钥匙到底怎么会跑进上锁的抽屉里？”','“How on earth did the keys end up inside the locked drawer?” / Mara asked / still holding / the only key.','how on earth 用于加强疑问语气，表达惊讶或难以理解。','钥匙在上锁抽屉里的情形令人困惑，因此使用强调问句。')],mistakes:[M('Mara said “How on earth” to make a neutral statement that she already knew exactly where the keys were.','Mara asked “How on earth” to express surprise about the keys’ unexplained location.','how on earth 强调困惑或惊讶，不是单纯陈述已知事实。')],quiz:[Q('how on earth',1,1,'“How on earth did this happen?” expresses?','surprise or disbelief','a neutral measurement','a polite hotel welcome','surprise or disbelief','how on earth 用于表达惊讶或难以置信。'),Q('how on earth',2,1,'Which question uses the phrase naturally?','How on earth did the boat reach the roof?','How on earth is exactly sixty minutes.','The how on earth welcomed the guests.','How on earth did the boat reach the roof?','反常情形引发的疑问可用 how on earth。'),Q('how on earth',3,1,'How on earth makes a question more?','emphatic','horizontal','hospitable','emphatic','该短语加强疑问语气。','word-formation'),Q('how on earth',4,1,'A speaker using how on earth is often?','astonished or frustrated','measuring the price calmly','listing household goods','astonished or frustrated','说话人常带有惊讶或不耐烦。')]});
D('however',{etymology:E('However combines how with ever. It can introduce a contrast, mean “to whatever degree,” or add emphasis to a question, depending on its position and punctuation.','however'),contexts:[C('however.s1','报告写作','The route is longer; however, it avoids the landslide zone and remains open throughout the winter.','这条路线更长；然而，它避开了滑坡区，整个冬季都保持开放。','The route is longer / however / it avoids the landslide zone / and remains open throughout the winter.','however 在此作连接副词，引出与前文形成对比的事实。','路线虽然较长，但更安全且冬季开放。')],mistakes:[M('The route is longer; however it is safer, and the report intended no contrast or shift in direction.','The route is longer; however, it is safer.','此处 however 引出转折，通常与前句用标点分隔。')],quiz:[Q('however',1,1,'At the start of a contrasting sentence, however means?','nevertheless or in contrast','in what way','an exact price','nevertheless or in contrast','s1 表示然而、不过。'),Q('however',2,2,'“However difficult it seems, try again” means?','no matter how difficult it seems','it is not difficult at all','the method is unknown','no matter how difficult it seems','s2 表示无论程度如何。'),Q('however',3,3,'“How, however, could they know?” uses however for?','emphasis in a question','a group of people','a hotel room','emphasis in a question','s3 可在疑问句中加强语气。'),Q('however',4,1,'Which punctuation is standard for a sentence adverb?','It was late; however, we continued.','It was late however we continued without punctuation.','However it was late.','It was late; however, we continued.','转折副词 however 通常与分句标点分隔。','grammar')]});
D('howl',{etymology:E('Howl comes from Middle English howlen and is probably imitative of a long, loud cry. It can mean an animal’s call, a person’s cry in pain or anger, a loud wind or laughter, or the cry itself as a noun.','howl'),contexts:[C('howl.s3','暴风夜晚','The wind began to howl through the narrow valley, rattling the shutters as the storm moved closer.','风开始在狭窄山谷中呼啸，风暴临近时震得百叶窗作响。','The wind began to howl / through the narrow valley / rattling the shutters / as the storm moved closer.','howl 在此指风发出的持续响亮声音。','风穿过山谷发出呼啸，属于风声义。')],mistakes:[M('The wind howled through the valley in complete silence, making no sound at all.','The wind howled loudly through the valley as the storm approached.','howl 指发出响亮长声，不可能是完全无声。')],quiz:[Q('howl',1,1,'A wolf may howl by making?','a long, high cry','a quiet purring sound','a short polite greeting','a long, high cry','howl 指狼等动物的长声嚎叫。'),Q('howl',2,2,'A person may howl in?','pain or anger','hospitable welcome only','sleep without sound','pain or anger','s2 可指痛苦或愤怒时大声喊叫。'),Q('howl',3,3,'Wind can howl when it?','makes a loud rushing sound','turns into a horse','becomes a household item','makes a loud rushing sound','s3 形容风发出呼啸声。'),Q('howl',4,4,'A howl can also be?','the long loud cry itself','a measure of engine power','a place for growing seedlings','the long loud cry itself','howl 也可作名词，表示嚎叫声。')]});
D('hub',{etymology:E('Hub is an English word of uncertain origin, first referring to the central part of a wheel. It now commonly means the central or most active point of a system or activity.','hub'),contexts:[C('hub.s1','交通规划','The renovated station has become a regional transport hub, connecting local buses with trains and airport shuttles.','翻修后的车站已成为区域交通枢纽，将当地公交、火车和机场接驳车连接起来。','The renovated station has become a regional transport hub / connecting local buses / with trains / and airport shuttles.','hub 指活动或连接集中的核心地点。','车站汇集并连接多种交通线路。')],mistakes:[M('The planner called an isolated stop with no connections a transport hub.','The planner called the station linking buses, trains, and shuttles a transport hub.','没有连接线路的孤立站点不是交通枢纽。')],quiz:[Q('hub',1,1,'A transport hub is?','a central point connecting routes','a person held as a hostage','a device for measuring temperature','a central point connecting routes','hub 指交通等活动的中心枢纽。'),Q('hub',2,1,'A city may be a hub for?','business and travel','only one quiet garden','a single horse’s hoof','business and travel','中心城市常汇集商业和交通活动。'),Q('hub',3,1,'Which place functions as a hub?','a station linking several transit lines','a dead-end path with no connections','a locked storage cupboard','a station linking several transit lines','连接多条线路的车站是枢纽。'),Q('hub',4,1,'Hub originally referred to the central part of a?','wheel','hothouse','hospital','wheel','hub 早期指车轮中心部分。','word-formation')]});
D('hubbub',{etymology:E('Hubbub is an English word of uncertain origin, recorded for a confused noise or uproar. It means loud, overlapping talk or a state of noisy confusion.','hubbub'),contexts:[C('hubbub.s1','车站大厅','The morning hubbub in the station came from travelers calling to one another, rolling suitcases, and waiting for delayed trains.','车站早晨的喧闹声来自旅客彼此呼喊、拖动行李箱以及等待晚点列车。','The morning hubbub in the station / came from travelers calling to one another / rolling suitcases / and waiting for delayed trains.','hubbub 指许多人同时说话造成的嘈杂声。','多种声音交叠构成大厅里的喧闹。')],mistakes:[M('The station was silent and empty, yet the report described a loud hubbub of overlapping voices.','The busy station filled with a hubbub of overlapping voices and movement.','安静空荡的空间没有喧闹的人声。')],quiz:[Q('hubbub',1,1,'A hubbub is?','a loud confused noise from many people','a calm single whisper','a unit of power','a loud confused noise from many people','hubbub 指嘈杂喧闹。'),Q('hubbub',2,2,'A state of hubbub is one of?','noisy confusion','perfect silence','steady horizontal motion','noisy confusion','s2 指混乱喧闹的状态。'),Q('hubbub',3,1,'Where might a hubbub arise?','a crowded station during delays','an empty quiet library after closing','a sealed jar in a cupboard','a crowded station during delays','拥挤且列车晚点的车站容易嘈杂。'),Q('hubbub',4,1,'Which sound best matches hubbub?','many overlapping conversations and calls','one clear clock chime','the silence of an empty room','many overlapping conversations and calls','许多人同时交谈呼喊形成嘈杂声。')]});
D('huckleberry',{etymology:E('Huckleberry combines huckle, an older regional name for certain small berries, with berry. It names a round dark blue or black berry that grows wild in parts of North America.','huckleberry'),contexts:[C('huckleberry.s1','野外采集','The field guide identifies the dark berries as huckleberries and advises visitors to confirm the species before tasting any wild fruit.','野外指南将这些深色浆果识别为越橘，并提醒访客尝食野果前先确认物种。','The field guide identifies the dark berries as huckleberries / and advises visitors / to confirm the species / before tasting any wild fruit.','huckleberry 指北美部分地区野生生长的深蓝或黑色浆果。','野外指南根据深色果实介绍该浆果，并提醒谨慎辨认。')],mistakes:[M('The guide identified a plastic bead as a huckleberry and told visitors to eat it.','The guide identified a round wild dark berry as a huckleberry and advised accurate species identification.','塑料珠不是浆果，且野生植物必须谨慎辨认。')],quiz:[Q('huckleberry',1,1,'A huckleberry is a?','round dark blue or black berry','large biting fly','household cleaning tool','round dark blue or black berry','huckleberry 指一种深色浆果。'),Q('huckleberry',2,1,'Huckleberries grow wild in parts of?','North America','the surface of Mars','every indoor cupboard','North America','这种浆果在北美部分地区野生生长。'),Q('huckleberry',3,1,'Which description fits a huckleberry?','a small dark wild berry','a brass musical instrument','a horse’s metal shoe','a small dark wild berry','小而深色的野生浆果符合描述。'),Q('huckleberry',4,1,'Before tasting a wild huckleberry, a visitor should?','confirm the plant species','assume every wild berry is safe','test it by touching a hornet','confirm the plant species','野果需确认物种后再考虑食用。')]});
D('huddle',{etymology:E('Huddle is of uncertain origin and is recorded from the sixteenth century. It can mean gathering close together, curling up for warmth or fear, a short team meeting, or a confused crowded mass.','huddle'),contexts:[C('huddle.s3','篮球比赛','The players formed a quick huddle near the bench to agree on a defensive plan before returning to the court.','球员们在回到球场前，在替补席附近快速围拢，商定防守方案。','The players formed a quick huddle / near the bench / to agree on a defensive plan / before returning to the court.','huddle 在此指队员短暂聚集讨论战术。','球员临时聚拢制定方案，符合团队会议义。')],mistakes:[M('The players held a huddle by spreading out across the court and refusing to speak to one another.','The players held a huddle by gathering closely to discuss their plan.','彼此分散且不交流不符合 huddle 的聚拢讨论义。')],quiz:[Q('huddle',1,1,'To huddle together is to?','gather closely in a group','stand far apart','move horizontally through the air','gather closely in a group','huddle 可指紧密聚集。'),Q('huddle',2,2,'A frightened child may huddle by?','curling up the body','sounding a horn','riding a horse','curling up the body','s2 指因寒冷或害怕而蜷缩身体。'),Q('huddle',3,3,'A team huddle is usually?','a brief gathering to plan','a long hotel stay','a unit of engine power','a brief gathering to plan','s3 指队员简短集合商议。'),Q('huddle',4,4,'A huddle of boxes might be?','a crowded, confused mass','a single orderly row','a group of wild berries','a crowded, confused mass','s4 可形容拥挤混乱的一团。')]});

})();
